(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["multimodal"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-qwen-vl-a-versatile-vision-language-2023"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-1\">一 · 从一张 4K 商品图进入在线服务说起</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-2\">二 · 旧栈的三段串行：编码、注入、解码各自为政</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-3\">三 · 为什么“把视觉 token 当固定开销”必然失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-4\">四 · 同卡部署的隐性冲突：编码器峰值挤压 KV</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-5\">五 · 精度规划不能一刀切：两侧的敏感度不同</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-6\">六 · 非改不可的工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-7\">七 · 分辨率平方律下的批调度失真：旧栈为何在在线服务里撑不住</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-8\">八 · 把“请求”还原成一条长度向量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-9\">九 · 并发上限由 KV 预算反推，而非由请求数决定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-10\">十 · 按视觉 token 预算切批，而不是按请求数切批</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-11\">十一 · 视觉编码器是串行瓶颈，SLO 要单独给它设预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-12\">十二 · 负载塑造方案，方案反过来限制负载</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-13\">十三 · 视觉 token 预算作为准入与切批的一等约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-14\">十四 · 视觉编码器的 kernel 形态与精度落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-15\">十五 · 累加精度：FP16 累加的溢出边界与 BF16 的取舍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-16\">十六 · FP8 与 NVFP4：缩放粒度决定误差落在哪里</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-17\">十七 · tcgen05、TMEM 与 2-SM MMA：Blackwell 的 kernel 结构变化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-18\">十八 · 精度规划与显存、带宽的联合账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-19\">十九 · 视觉 token 预算下的精度分层与批内长尾边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-20\">二十 · 视觉 token 的平方律与 KV 账本的第一性原理</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-21\">二十一 · 三本账：权重、激活与 KV 的分别核算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-22\">二十二 · 分页、压缩、复用与卸载：四种手段的代价结构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-23\">二十三 · 带宽瓶颈的位置：预填看算力，解码看访存</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-24\">二十四 · 一个可复算的显存预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-25\">二十五 · 视觉 token 预算的失效边界与同卡部署的显存挤压</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-26\">二十六 · 视觉 token 预算作为切批的第一性变量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-27\">二十七 · 连续批处理在视觉侧的两个断点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-28\">二十八 · Chunked prefill 与视觉 token 的注入粒度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-29\">二十九 · 优先级、抢占与 KV 回收的次序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-30\">三十 · 分离式预填/解码与视觉编码器的三段部署</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-31\">三十一 · 尾延迟的度量与分桶粒度的调参闭环</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-32\">三十二 · 视觉 token 预算切批的边界与失效条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-33\">三十三 · 切分维度与视觉负载的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-34\">三十四 · NVLink 5 与 NVSwitch 的带宽账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-35\">三十五 · All-Reduce 与 All-to-All 的瓶颈判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-36\">三十六 · NIXL 传输与分离式部署的通信成本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-37\">三十七 · 通信何时成为瓶颈的工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-38\">三十八 · 视觉侧与语言侧分离部署时的通信边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-39\">三十九 · 精度塌陷：视觉侧先崩，语言侧后崩</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-40\">四十 · OOM：峰值不在解码，在编码器与预填的交界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-41\">四十一 · 批抖动与尾延迟：按 token 预算切批，不按请求数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-42\">四十二 · 静默降级：没有报错，只有分位在漂</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-43\">四十三 · 监控面与回滚闸门：把视觉 token 预算做成可观测变量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-44\">四十四 · 分辨率分桶失效与视觉编码器显存挤占：诊断路径与回滚边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-45\">四十五 · 口径先于数字：把视觉 token 当计量单位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-46\">四十六 · 硬件档位与精度口径：三档不可混算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-47\">四十七 · TTFT 与 TPOT 的拆分：编码器是独立预算项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-48\">四十八 · 吞吐的分母：并发上限由 KV 反推，不由请求数决定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-49\">四十九 · 哪些提升不可比：五类常见错配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-50\">五十 · 监控口径：把分位与方差写进指标</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-51\">五十一 · 视觉 token 预算下的口径边界与失效条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-52\">五十二 · 迁移的第一道闸门：压缩率与位置编码的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-53\">五十三 · 分辨率分桶的迁移：桶边界随模型重画</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-54\">五十四 · 分离部署的边界：通信开销吃掉多少收益</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-55\">五十五 · 量化的迁移风险：视觉特征比文本更敏感</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-56\">五十六 · 规模上限：三个约束谁先撞墙</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-57\">五十七 · 边界在哪里：迁移到别的模型与领域时要重算的那几个量</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:543px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 543.2 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"461.2\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">请求进入后按图像分辨率与文本长度分桶，估算视觉 token 数与总序列…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"461.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">图像预处理与分块后送入视觉编码器，按桶批处理以摊薄编码器延迟。</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"461.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">视觉 token 经压缩与合并模块降采样，输出固定预算的视觉 toke…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"461.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">跨模态注意力在预填阶段把视觉 token 注入语言模型 KV，形成统一…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"461.2\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">语言模型自回归解码，KV cache 按总 token 数计费并按批调…</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-1\">一 · 从一张 4K 商品图进入在线服务说起</h3>\n<p>设想一个电商图文问答服务：用户上传一张 3840×2160 的商品实拍图，问“图中左下角标签上的型号是什么”。请求进入网关时，调度器看到的不是一个“请求”，而是两段长度极不确定的序列——图像侧和文本侧。图像侧按分块送入视觉编码器，视觉 token 数按分辨率平方增长：</p>\n<div class=\"formula\">$$T_{\\mathrm{vis}}=\\left\\lceil \\frac{H\\cdot W}{P^{2}}\\right\\rceil,\\quad T_{\\mathrm{total}}=T_{\\mathrm{vis}}^{\\prime}+T_{\\mathrm{text}},\\quad M_{\\mathrm{KV}}=2\\,L\\,H_{kv}\\,d\\,T_{\\mathrm{total}}\\,b$$</div>\n<p>同一时刻，批里还有一张 224×224 的头像图和一段 800 token 的商品描述。三者的视觉 token 数相差一个数量级以上，但它们在旧式调度器眼里是三个“请求”。这就是 Qwen-VL 之前多模态推理栈的核心矛盾：<strong>成本变量是 token，调度单位却是请求</strong>。视觉 token 数随分辨率平方增长，直接决定预填计算量、KV cache 占用与可接纳并发；而按请求数切批的做法，让短请求为长请求的编码器前向和预填买单。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-2\">二 · 旧栈的三段串行：编码、注入、解码各自为政</h3>\n<p>论文之前的典型推理路径是“图像预处理与分块 → 视觉编码器前向 → 跨模态注意力注入 → 语言模型自回归解码”，四段在一个进程里顺序执行。问题不在单段效率，而在段间的耦合方式。视觉编码器是串行瓶颈：一张高分辨率图的分块数远多于文本 token，编码器前向必须等全部分块完成才能产出特征，这段时间语言模型的 KV cache 已经按最大可能长度预留，显存被“占着不用”。跨模态注意力在预填阶段一次性注入视觉 token，意味着预填的计算量与 KV 写入量都随 $T_{\\mathrm{vis}}^{\\prime}$ 线性上升；解码阶段只读 KV，于是压缩率成了唯一能同时削减预填和 KV 的杠杆。</p>\n<p>工程代价可以拆成三笔账。第一笔是显存：$M_{\\mathrm{KV}}$ 与 $T_{\\mathrm{total}}$ 成正比，长图像请求会把并发上限压到个位数，准入控制若不显式估算视觉 token，就会出现“看似还有空卡、实际一收请求就 OOM”的失真。第二笔是首 token 延迟：编码器前向无法与解码重叠，高分辨率请求的首 token 延迟由编码器单独支配，且随分块数增长。第三笔是批内长尾：按请求数切批时，批的完成时间由最长的图像请求决定，短请求的 KV 早已算完却只能等待，首 token 延迟分位被拉高。</p>\n<table class=\"mini\"><thead><tr><th>旧栈环节</th><th>成本来源</th><th>对推理系统的直接后果</th></tr></thead><tbody><tr><td>视觉编码器前向</td><td>分块数随分辨率增长，串行执行</td><td>首 token 延迟被编码器支配，无法与解码重叠</td></tr><tr><td>跨模态注入</td><td>预填阶段一次性写入全部视觉 token</td><td>预填计算与 KV 写入随 $T_{\\mathrm{vis}}^{\\prime}$ 线性上升</td></tr><tr><td>自回归解码</td><td>KV 按总 token 数计费</td><td>长图像请求压缩并发，准入估算失真</td></tr></tbody></table>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-3\">三 · 为什么“把视觉 token 当固定开销”必然失效</h3>\n<p>旧栈最普遍的简化是把视觉 token 当作一个固定常数写进容量模型：每请求预留 N 个视觉 token 的 KV 空间。这个假设在头像图上浪费显存，在 4K 图上直接突破上限。真实分布是重尾的——少数高分辨率请求贡献了大部分 token 预算。用固定常数做准入，等于用均值去赌尾部：并发上限被高估，长图像请求一进来就触发抢占或 OOM，而抢占带来的重算又把延迟进一步推高。</p>\n<p>正确的做法是把分辨率与视觉 token 数提升为一等调度参数。调度器在准入时读取图像尺寸与文本长度，估算 $T_{\\mathrm{vis}}$ 与 $T_{\\mathrm{total}}$，按视觉 token 预算而非请求数切批，并把请求放入对应分辨率桶。桶的作用是让批内 $T_{\\mathrm{vis}}$ 方差可控：桶过细，每桶请求少、批小、编码器利用率低；桶过粗，长尾重新出现。这个粒度必须按线上视觉 token 分布调参，并监控首 token 延迟的分位而非均值。压缩与合并模块的降采样率则决定了 $T_{\\mathrm{vis}}^{\\prime}$，它同时削减预填计算与 KV 写入，但压缩率越高，定位与文本阅读所需的细粒度空间信息损失越大——这是精度与容量的显式权衡，不是免费的开关。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-4\">四 · 同卡部署的隐性冲突：编码器峰值挤压 KV</h3>\n<p>旧栈常把视觉编码器与语言模型放在同一张卡上，理由是“省一次跨节点传输”。代价是显存的分时竞争：编码器前向的激活峰值与语言模型的 KV cache 共享同一显存档位。当批里混入高分辨率请求时，编码器峰值抬高，KV cache 可用的剩余空间被压缩，调度器不得不降低并发或驱逐已有请求的 KV。这种冲突在稳态吞吐上表现为抖动——同样的请求组合，有时能收、有时被拒，容量规划失去可预测性。</p>\n<p>分离部署是论文给出的结构性答案：视觉侧按分辨率分桶批处理，语言侧按文本与视觉 token 总长度管理 KV，两类负载的批调度与精度策略解耦。代价是跨节点传输视觉 token 特征，通信开销与失败重试必须计入端到端延迟预算；在 Blackwell 的 NVLink 5 域内，这段传输可以走 NIXL 一类的点对点通路，但它仍然是一个需要显式建模的延迟项，而不是零成本。分离部署还带来一个接口约束：跨模态注意力的位置编码与分辨率分桶必须在推理时与训练一致，否则视觉 token 合并会破坏定位与文本阅读能力——这是推理栈不能自行其是的地方。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-5\">五 · 精度规划不能一刀切：两侧的敏感度不同</h3>\n<p>旧栈的另一个惯性是把量化当成全局开关：语言模型上了 FP8，视觉编码器顺手也上。但两侧的数值敏感度并不相同。语言模型的 KV 与权重对 FP8 的容忍度已有较多工程经验；视觉编码器的输出特征要经过压缩合并再注入跨模态注意力，低精度误差会在空间定位与细粒度文本阅读上被放大。材料未给出 NVFP4/FP8 下的具体精度代价，因此工程判断只能是：视觉编码器与语言模型分别做精度评估，分别规划显存，不共享同一套量化配置。在 Blackwell 上，这意味着 tcgen05 与 TMEM 的算子选择、2-SM MMA 的切分策略要按两侧的精度档位分别落地，而不是一套 kernel 通吃。</p>\n<p>精度分侧还影响容量模型。视觉侧用较高精度，编码器激活峰值更高，分离部署的必要性更强；语言侧用 NVFP4/FP8，KV 的每 token 字节数下降，$M_{\\mathrm{KV}}$ 公式里的 $b$ 变小，并发上限随之抬升。两侧的精度决策通过显存档位与通信量耦合在一起，必须在容量规划时联立求解，而不是先定精度再算容量。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-6\">六 · 非改不可的工程判断</h3>\n<p>把上述痛点收拢，旧栈失效的根源是一条链：视觉 token 数随分辨率平方增长 → KV 与预填成本随总 token 数上升 → 按请求数切批使批内方差失控 → 编码器串行瓶颈与同卡显存竞争进一步放大首 token 延迟分位。任何单点优化都堵不住这条链：只压缩不调度，长尾仍在；只调度不压缩，KV 仍会突破上限；只分离部署不做精度分侧，显存规划仍然失真。Qwen-VL 的推理主线因此把压缩率、分辨率分桶粒度与 KV 计费绑定到同一个批调度决策上——视觉 token 预算成为切批、准入与精度规划的共同货币。对 Blackwell 部署而言，这条判断的直接落点是：调度器读尺寸、算 token、进桶、按预算切批；视觉编码器与语言模型各自规划精度与显存；跨节点传输计入延迟预算；监控盯住视觉 token 数分布、批内方差与首 token 延迟分位，而不是平均吞吐。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-7\">七 · 分辨率平方律下的批调度失真：旧栈为何在在线服务里撑不住</h3>\n<p>设想一个面向电商与文档问答的在线服务：同一分钟内涌入的是缩略图商品图、手机拍摄的整页发票、以及 4K 截图，文本侧从一句提问到整段 OCR 校对不等。旧栈的典型做法是把请求按到达顺序凑成固定请求数的批，图像统一缩放到一个预设边长，视觉编码器与语言模型同卡串行执行，KV cache 按经验值预留。这套做法在纯文本时代成立，因为序列长度分布窄、可预测；一旦图像进入请求，长度分布立刻变成重尾。视觉 token 数由分块边长决定，<div class=\"formula\">$$T_{\\mathrm{vis}}=\\left\\lceil \\frac{H\\cdot W}{P^{2}}\\right\\rceil,\\quad T_{\\mathrm{total}}=T_{\\mathrm{vis}}^{\\prime}+T_{\\mathrm{text}},\\quad M_{\\mathrm{KV}}=2\\,L\\,H_{kv}\\,d\\,T_{\\mathrm{total}}\\,b$$</div>分辨率翻倍即 token 数四倍，KV 占用按总 token 线性放大。固定请求数切批的真实代价是：一个 4K 截图请求把整批的预填时长与 KV 峰值一起抬高，同批的短请求既拿不到首 token，也把显存额度占满，准入控制随后误判为“并发已满”，吞吐塌陷而 GPU 并未真正算满。</p>\n<p>第二个失效点是视觉编码器与语言模型同卡部署时的显存争抢。编码器前向是串行段，其峰值激活与分块特征驻留会临时挤压 KV cache 的可用空间；旧栈按静态上限预留 KV，等于把编码器峰值当成常态开销来付，结果是批容量被系统性低估。更隐蔽的是压缩与合并环节被当成训练侧设计：推理时若压缩率与训练不一致，或分辨率分桶与训练的位置编码约定不匹配，视觉 token 合并会破坏定位与文本阅读能力，表现为框坐标漂移、表格行列错位，而这类退化不会在吞吐指标上暴露，只会以重试与人工兜底的形式变成成本。跨模态注意力在预填阶段一次性注入、解码阶段只读 KV，因此压缩率越高预填与 KV 写入越省，但精度权衡必须由服务侧显式承担，不能默认压缩是免费的。</p>\n<p>第三个失效点是批内方差与桶粒度。按请求数切批忽略分辨率差异，批内长尾直接拉高首 token 延迟分位；桶过细则批小、编码器延迟摊不薄，桶过粗则长尾回归。旧栈缺少以视觉 token 预算为单位的准入估算，长图像请求会悄悄压缩可接纳并发，SLO 以首 token 延迟为主时，视觉编码器延迟必须单独设预算，否则语言侧的解码优化无法兑现为端到端改善。分离部署可解耦两类负载的批调度与精度策略，代价是跨节点传输视觉 token 特征，通信开销与失败重试要计入尾延迟；同卡分时部署则要把编码器峰值显存从 KV 预算中扣除。这些边界共同指向一个工程判断：多模态推理的成本变量不是请求数而是视觉 token 预算，切批、准入与显存规划必须绑定到同一预算上，否则任何单点优化都会被长尾请求吞掉。</p>\n<table class=\"mini\"><thead><tr><th>旧栈做法</th><th>失效条件</th><th>系统代价</th></tr></thead><tbody><tr><td>固定请求数切批</td><td>批内分辨率方差大</td><td>首 token 延迟分位抬升、短请求拖尾</td></tr><tr><td>统一缩放边长</td><td>文档与截图类输入</td><td>文本阅读与定位精度退化、重试成本</td></tr><tr><td>编码器与 LM 同卡静态预留 KV</td><td>高分辨率桶集中到达</td><td>批容量低估、并发误判</td></tr><tr><td>按经验值预留 KV</td><td>视觉 token 占比高</td><td>显存峰值突破、准入拒绝率上升</td></tr></tbody></table>\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-8\">八 · 把“请求”还原成一条长度向量</h3>\n<p>在 Qwen-VL 的推理链路上，一个请求不是“一张图加一句话”，而是一条可计算的长度向量：图像经分块后产生的视觉 token 数、文本 token 数，以及两者拼接后的总序列长度。视觉 token 数由分辨率与分块尺寸决定，随分辨率平方增长：</p>\n<div class=\"formula\">$$T_{\\mathrm{vis}}=\\left\\lceil \\frac{H\\cdot W}{P^{2}}\\right\\rceil,\\quad T_{\\mathrm{total}}=T_{\\mathrm{vis}}^{\\prime}+T_{\\mathrm{text}}$$</div>\n<p>其中 $T_{\\mathrm{vis}}^{\\prime}$ 是压缩合并后的预算值，而非编码器原始输出。这条公式的工程含义是：调度器在请求进入时就必须同时拿到三个量——原始分辨率、压缩率、文本长度——否则无法估算后续的 KV 占用。测量口径上，应把每个请求记录为三元组（原始 $T_{\\mathrm{vis}}$、压缩后 $T_{\\mathrm{vis}}^{\\prime}$、$T_{\\mathrm{text}}$），并按 $T_{\\mathrm{total}}$ 分桶统计分布，而不是只统计“平均图像大小”。只统计请求数会掩盖真实负载形态：同样一百个请求，全部是低分辨率短文本与全部是高分辨率长文本，对 KV cache 的压力相差一个量级以上。可核查的做法是对每个桶输出计数、$T_{\\mathrm{total}}$ 的均值与高分位（如 p50/p90/p99），以及批内 $T_{\\mathrm{total}}$ 的方差——方差才是长尾的直接来源。</p>\n<p>具体例子：文档阅读类请求往往分辨率高、文本短，视觉 token 占绝对主导；而图文问答类请求分辨率中等、文本偏长，两者混在同一批里，批内长度差异被放大。代价落在首 token 延迟上：视觉编码器必须等整批中最慢的那张图编码完成，短请求被迫陪跑。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-9\">九 · 并发上限由 KV 预算反推，而非由请求数决定</h3>\n<p>KV cache 按总 token 数计费，视觉 token 与文本 token 共享同一预算：</p>\n<div class=\"formula\">$$M_{\\mathrm{KV}}=2\\,L\\,H_{kv}\\,d\\,T_{\\mathrm{total}}\\,b$$</div>\n<p>式中 $b$ 为该请求在批内的实际驻留量。工程上正确的并发规划顺序是：先定显存档位与留给 KV 的空间，再用单请求 $M_{\\mathrm{KV}}$ 的分布反推可接纳并发，而不是先定并发数再祈祷显存够用。由于 $T_{\\mathrm{total}}$ 随分辨率剧烈波动，固定并发数在长图像请求到来时会直接突破上限；正确做法是准入控制里显式估算每个候选请求的 $M_{\\mathrm{KV}}$，按剩余 KV 预算做装箱。测量口径应包含：KV 占用随时间的曲线、被拒绝或排队请求的 $T_{\\mathrm{total}}$ 分布、以及 KV 峰值与显存上限的比值。若只看平均占用，会漏掉由少数长图像请求造成的瞬时峰值。</p>\n<p>具体例子：一个高分辨率文本阅读请求的压缩后视觉 token 预算若显著高于普通问答请求，它单独占用 KV 的量可能相当于数个短请求之和；若调度器按请求数放行，这一条请求就会把整批的 KV 余量吃光，后续请求只能排队，表现为首 token 延迟分位突然抬升。代价是吞吐与延迟的取舍：提高压缩率能放大可接纳并发，但压缩率直接绑定定位与文本阅读精度，需与训练侧接口保持一致。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-10\">十 · 按视觉 token 预算切批，而不是按请求数切批</h3>\n<p>批内长度不齐的根源是分辨率差异。按请求数切批时，调度器对批内 $T_{\\mathrm{total}}$ 的方差无控制力，长请求会把整批的首 token 延迟拉到自己的水平；按视觉 token 预算切批，则把“批的总 token 数”作为约束，短请求可以多塞、长请求单独成批或与同桶请求合并。伪代码思路：</p>\n<div class=\"formula\">$$\\text{for each bucket: } \\sum_{i\\in\\text{batch}} T_{\\mathrm{total},i}\\le B_{\\mathrm{tok}},\\ \\ \\text{minimize } \\mathrm{Var}(T_{\\mathrm{total}})$$</div>\n<p>这里的 $B_{\\mathrm{tok}}$ 是批级 token 预算，与 KV 预算和预填计算量同时挂钩。测量口径要能验证切批策略是否生效：批内 $T_{\\mathrm{total}}$ 的方差、批利用率（实际 token 数除以预算）、以及首 token 延迟的 p99 与 p50 之比。若 p99/p50 比值大，说明长尾未被切批吸收，应调细分辨率分桶或降低单批 token 预算。代价是桶过细导致批小、编码器与语言模型的批利用率下降，吞吐受损；桶过粗则长尾回归。这是一个需要用分布数据调参的权衡，不能靠固定阈值。</p>\n<p>具体例子：同一分辨率桶内，文本长度仍可能差异明显，因此切批约束应同时看 $T_{\\mathrm{vis}}^{\\prime}$ 与 $T_{\\mathrm{text}}$，而非只按图像分桶。若只按图像分桶，长文本请求仍会在批内拖尾。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-11\">十一 · 视觉编码器是串行瓶颈，SLO 要单独给它设预算</h3>\n<p>视觉编码器前向在整条链路上是串行的：预处理与分块完成后才能编码，编码完成后才能压缩合并、注入 KV。这意味着首 token 延迟可分解为编码段与预填段之和，SLO 若只对端到端设一个数，就无法定位瓶颈。可核查的测量口径是把首 token 延迟拆成编码器前向时间、压缩合并时间、预填注入时间、以及排队等待时间四项，分别统计分位。按分辨率分桶批处理能摊薄编码器延迟：同桶请求共享一次批前向，单请求分摊的编码成本下降；但桶利用率低时，批前向的固定开销反而占主导。</p>\n<p>具体例子：若视觉编码器与语言模型同卡部署，编码器前向的峰值显存会挤压 KV cache 空间，表现为编码阶段 KV 可用量瞬时下降，调度器不得不暂缓放行新请求。代价是显存与延迟的耦合：分离部署可解耦两类负载的批调度与精度策略，但跨节点传输视觉 token 特征要计入通信开销与失败重试，且传输延迟本身进入首 token 关键路径。工程判断是：当编码器峰值显存与 KV 预算争抢同一张卡时，分离部署的通信代价通常小于同卡争抢造成的调度抖动；反之当请求以低分辨率短文本为主、编码器负载轻时，同卡部署更省通信。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-12\">十二 · 负载塑造方案，方案反过来限制负载</h3>\n<p>负载形态不是外部给定常量，它被方案反向塑形。压缩率提高会降低单请求 $T_{\\mathrm{total}}$，从而抬高可接纳并发、降低首 token 延迟，但压缩率与训练侧接口绑定，过高的降采样会破坏定位与文本阅读能力，于是“能接多少请求”与“能答多准”在同一参数上耦合。分辨率分桶粒度同样反向作用：桶越细，批内方差越小、长尾越短，但桶利用率下降使编码器批变小，单位请求的编码固定开销上升，等效吞吐下降；桶越粗则相反。准入控制若按 $T_{\\mathrm{total}}$ 严格装箱，会优先接纳短请求，长图像请求排队时间变长，实际服务的请求分布被推向短边——这是方案对负载分布的直接改写。</p>\n<p>可核查的监控口径应覆盖三层：请求层（$T_{\\mathrm{vis}}$、$T_{\\mathrm{vis}}^{\\prime}$、$T_{\\mathrm{text}}$ 的分布与分位）、批层（批内方差、批利用率、切批拒绝率）、服务层（首 token 延迟分位、KV 峰值占比、编码器与预填段时间占比）。三层数据必须能对齐到同一时间窗，否则无法判断长尾是来自请求分布变化还是切批策略退化。具体例子：当文档阅读类请求占比上升时，$T_{\\mathrm{vis}}^{\\prime}$ 分布右移，KV 峰值占比上升，若压缩率不变，可接纳并发被动下降，首 token 延迟 p99 抬升；此时若盲目调粗分桶以提升批利用率，长尾会进一步恶化。正确的动作是先看批内方差与桶利用率，再决定是调压缩率、调分桶粒度还是调批 token 预算——三者中任一改动都会反向改变负载的可接纳形态，必须用同一套测量口径闭环验证。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-13\">十三 · 视觉 token 预算作为准入与切批的一等约束</h3>\n<p>Qwen-VL 的负载形态不是「请求数 × 固定序列长度」，而是分辨率驱动的重尾分布：视觉 token 数按 <span class=\"formula\">$$T_{\\mathrm{vis}}=\\left\\lceil \\frac{H\\cdot W}{P^{2}}\\right\\rceil$$</span> 随像素面积平方级增长，再经压缩合并降到预设预算 <span class=\"formula\">$$T_{\\mathrm{vis}}^{\\prime}$$</span>，与文本长度拼成 <span class=\"formula\">$$T_{\\mathrm{total}}=T_{\\mathrm{vis}}^{\\prime}+T_{\\mathrm{text}}$$</span>。KV 占用按 <span class=\"formula\">$$M_{\\mathrm{KV}}=2\\,L\\,H_{kv}\\,d\\,T_{\\mathrm{total}}\\,b$$</span> 线性计费，因此单请求显存不是常数，而是一个由图像尺寸决定的随机变量。工程上必须把这个变量前移到准入控制：调度器在请求到达时读取图像尺寸与文本长度，先估算 <span class=\"formula\">$$T_{\\mathrm{total}}$$</span> 与 <span class=\"formula\">$$M_{\\mathrm{KV}}$$</span>，再决定是否接纳、放入哪个分辨率桶。若把视觉 token 当作固定开销，长图像请求会直接突破并发上限——这是该方案最先失效的地方。</p>\n<p>切批口径必须从「请求数」改为「token 预算」。批内长度不齐的根源是分辨率差异，按请求数切批会让短请求排队等待长请求，首 token 延迟分位被长尾拉高；按视觉 token 预算切批则把批内方差压到预算之内。代价是桶利用率下降：预算切得越紧，批越小，视觉编码器前向的摊薄效果越差，编码器串行瓶颈更突出。分辨率分桶粒度是同一矛盾的另一个旋钮——桶过细导致每桶请求稀疏、批小延迟高，桶过粗导致桶内长尾、方差回升。可核查的测量口径应固定为三项：视觉 token 数分布的分位值（p50/p90/p99）、批内 <span class=\"formula\">$$T_{\\mathrm{total}}$$</span> 的方差、以及首 token 延迟的分位曲线；三者必须同窗口采集，否则无法判断长尾来自负载还是来自切批策略。</p>\n<p>视觉编码器与语言模型同卡部署时，编码器峰值显存会挤压 KV cache 空间，这是显存规划上的硬冲突：编码器批越大，摊薄越好，但峰值激活占用越高，可接纳并发反而下降。分离部署解耦了两类负载的批调度与精度策略，代价是跨节点传输视觉 token 特征，通信开销与失败重试必须计入端到端延迟预算，且传输的是压缩后的 <span class=\"formula\">$$T_{\\mathrm{vis}}^{\\prime}$$</span> 而非原始特征，压缩率越高传输越省、但定位与文本阅读精度需权衡。跨模态注意力在预填阶段一次性注入、解码阶段只读 KV，意味着压缩率直接决定预填计算与 KV 写入量，也决定了解码阶段的并发上限。SLO 应以首 token 延迟为主指标，并为视觉编码器单独设预算——把编码器延迟混入整体 SLO 会让桶粒度调参失去可观测性。</p>\n<table class=\"mini\"><thead><tr><th>负载维度</th><th>塑造方案的机制</th><th>方案反向限制负载的边界</th></tr></thead><tbody><tr><td>分辨率分布</td><td>决定 <span class=\"formula\">$$T_{\\mathrm{vis}}$$</span> 与分桶粒度</td><td>桶过粗则长尾回升，过细则批小、编码器延迟升</td></tr><tr><td>并发</td><td>受 KV 总 token 预算反推</td><td>长图像请求压缩可接纳并发，需准入估算</td></tr><tr><td>批大小</td><td>按 token 预算而非请求数切批</td><td>预算紧则摊薄不足，编码器串行瓶颈放大</td></tr><tr><td>SLO</td><td>首 token 延迟为主，编码器单独预算</td><td>压缩率提高省预填，但精度代价需实测</td></tr></tbody></table>\n<p>量化是这条链路上尚未闭合的接口：材料未给出 NVFP4/FP8 下视觉编码器与语言模型的精度代价，视觉特征对低精度更敏感的可能性必须分别实测，不能把语言模型的量化结论直接外推到视觉侧。监控需覆盖视觉 token 数分布、批内方差与首 token 延迟分位，三者共同构成判断「负载塑造方案」还是「方案限制负载」的可核查依据——当分位延迟随视觉 token p99 同步抬升，说明是负载重尾；当方差稳定而延迟仍高，说明是切批或桶粒度配置失效。</p>\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-14\">十四 · 视觉编码器的 kernel 形态与精度落点</h3>\n<p>Qwen-VL 的视觉编码器在推理侧承担的是分块后的稠密卷积与注意力混合前向，其 kernel 选择与语言模型解码路径完全不同：视觉侧是计算密集、批内尺寸整齐的短时突发，语言侧是访存密集、逐 token 串行的长尾负载。把两者放进同一张卡的同一套精度策略里，是部署中最常见的错误。视觉编码器对低精度的敏感度集中在特征归一化与位置相关的空间响应上——一旦把 patch embedding 与归一化层压到 FP8，定位框回归与文本阅读的空间对齐会先于分类精度退化。工程上的稳妥切分是：卷积与线性层走 FP8 或 BF16，归一化、softmax 与位置编码保持 FP16/BF16 累加，视觉 token 合并前的特征保留高精度副本。代价直接体现在显存与带宽上：视觉编码器若整段走 FP16，其峰值激活显存按分辨率平方增长，与 KV cache 争夺同一显存档位；若走 FP8，激活减半但需要额外的缩放因子张量，且缩放因子的粒度（per-tensor 还是 per-block）决定了量化误差在空间维度上的分布是否均匀。</p>\n<p>以一张高分辨率文档图像为例，分块后视觉 token 数按 <span class=\"formula\">$$T_{\\mathrm{vis}}=\\left\\lceil \\frac{H\\cdot W}{P^{2}}\\right\\rceil$$</span> 增长，其中 H、W 为图像高宽，P 为 patch 边长。该式说明分辨率翻倍即 token 数四倍，编码器前向的 FLOPs 与激活显存同步四倍，而压缩合并模块的降采样率是唯一能把这条曲线压回来的杠杆。压缩率越高，注入语言模型的序列越短，预填计算与 KV 写入越省，但定位与文本阅读所需的细粒度空间信息被一并抹掉——这就是精度与压缩在视觉侧的耦合点，量化误差与降采样误差会叠加而非独立。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-15\">十五 · 累加精度：FP16 累加的溢出边界与 BF16 的取舍</h3>\n<p>视觉编码器与语言模型的矩阵乘在 Tensor Core 上执行时，输入精度与累加精度是两件事。FP16 输入配 FP16 累加在视觉侧的长序列注意力中会出现溢出：注意力分数在 softmax 前的指数项与 value 加权求和的动态范围超出 FP16 的表示上限，表现为数值饱和而非随机舍入误差。BF16 用 8 位指数换回动态范围，代价是 7 位尾数带来的相对误差在累加链路上放大——视觉特征经过多层残差叠加后，BF16 累加的误差会以层数线性累积，而 FP16 累加在未溢出时尾数更宽、误差更小。工程判断是：视觉编码器的注意力与残差路径优先 FP16 累加并配合缩放，线性层可走 BF16；语言模型的预填阶段因序列长、累加链长，BF16 累加的误差在 logits 上的影响需用输出端的校准观测，而不是凭精度标签假定。</p>\n<p>累加精度的代价不在算力而在可观测性：混合累加策略要求每个 kernel 明确声明输入、累加、输出三段精度，否则框架默认值会在不同算子间漂移，导致同一批请求的数值行为不可复现。对按视觉 token 预算切批的调度器而言，这意味着批内不同分辨率桶可能落在不同精度路径上，首 token 延迟的方差里混入了数值路径差异。一个具体例子是同一批内混入低分辨率缩略图与高分辨率文档图：前者 token 少、累加链短，后者 token 多、累加链长，若两者共用同一 BF16 累加配置，长链请求的 logits 偏差更大，表现为同一提示下输出分布漂移。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-16\">十六 · FP8 与 NVFP4：缩放粒度决定误差落在哪里</h3>\n<p>Blackwell 的第五代 Tensor Core 对 FP8 与 NVFP4 的原生支持把量化从“能不能跑”推进到“误差落在哪个维度”。FP8 的 E4M3 与 E5M2 两种格式在视觉侧的分工不同：E4M3 尾数多、适合权重与激活，E5M2 动态范围大、适合梯度类或动态范围跨度大的中间量。NVFP4 的块缩放（block scaling）把缩放因子从 per-tensor 下沉到更细的块粒度，使视觉特征在空间上非均匀的动态范围被逐块吸收——这对文档图像尤其关键，因为文本区域与空白背景的激活幅度差异极大，per-tensor 缩放会被空白区拉低整体尺度，文本区的细笔画响应被压掉。块缩放粒度越细，量化误差越局部化，但缩放因子本身的存储与读取开销上升，在带宽受限的视觉编码器前向中会转化为实际延迟。</p>\n<div class=\"formula\">$$\\hat{x}=s\\cdot q,\\quad s=\\frac{\\max(|x|)}{2^{b-1}-1},\\quad \\Delta x\\approx \\frac{s}{2}$$</div>\n<p>该式逐项说明：q 为量化后的整数，s 为缩放因子，b 为位宽，Δx 为量化步长即误差上界的一半。块缩放的本质是让 s 随块变化，从而让 Δx 跟随局部动态范围收缩；代价是每个块多一个 s 的读写，块越小，元数据带宽占比越高。对视觉编码器，这意味着 NVFP4 的收益必须与压缩合并模块的降采样率联合评估：压缩率已经把 token 数降下来，若再叠加激进量化，定位精度的退化会从两个方向同时到来，且难以归因。语言模型侧的 NVFP4 权重压缩主要省的是解码阶段的权重带宽，而视觉侧的 NVFP4 省的是编码器激活显存，两者对首 token 延迟的贡献路径不同，必须分开度量。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-17\">十七 · tcgen05、TMEM 与 2-SM MMA：Blackwell 的 kernel 结构变化</h3>\n<p>tcgen05 是 Blackwell 上 Tensor Core 的指令族接口，其关键变化是把矩阵乘的累加器从寄存器文件迁移到 TMEM（Tensor Memory）。TMEM 是 SM 内一块专用的大容量累加存储，使 MMA 的累加结果不必在寄存器与共享内存之间反复搬运。对视觉编码器这种批内尺寸整齐、矩阵乘密集的前向，TMEM 的直接收益是减少累加器的寄存器压力，让更多 warp 参与流水，代价是 TMEM 的容量约束了单次 MMA 的 tile 形状——tile 过大时累加器放不下，必须切分，切分又引入额外的同步。2-SM MMA 则让两个 SM 协作完成一次更大的矩阵乘，把单 SM 的 tile 上限翻倍，适合视觉编码器中通道数大、空间维度规整的卷积展开矩阵。其工程代价是跨 SM 的同步与数据交换，在批尺寸偏小时协作开销摊不薄，反而拉低利用率。</p>\n<p>把这三项特性落到 Qwen-VL 的推理链路上：视觉编码器前向适合 2-SM MMA 的大 tile，因为分块后的批内 patch 数整齐；语言模型的预填阶段序列长但批内长度不齐，2-SM 协作的收益被批内方差吃掉；解码阶段是逐 token 的瘦矩阵乘，TMEM 的累加优势主要体现在减少寄存器溢出而非提升算力。一个具体判断是：在按视觉 token 预算切批的调度下，视觉桶的批尺寸由桶内请求数决定，桶过细则批小、2-SM 协作不划算，桶过粗则长尾拉高首 token 延迟分位——kernel 选择与分桶粒度是同一个决策的两面，不能分开调。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-18\">十八 · 精度规划与显存、带宽的联合账</h3>\n<p>把精度策略写成一张按路径拆分的账，才能避免“整模型一个精度标签”的粗放做法。视觉编码器的激活显存与语言模型的 KV cache 共享同一显存档位，而两者的精度选择对显存的边际影响不同：视觉侧降精度省的是瞬时激活峰值，语言侧降精度省的是权重常驻与解码带宽。KV cache 的占用按 <span class=\"formula\">$$M_{\\mathrm{KV}}=2\\,L\\,H_{kv}\\,d\\,T_{\\mathrm{total}}\\,b$$</span> 计费，其中 L 为层数，H_kv 为 KV 头数，d 为头维，T_total 为视觉与文本 token 总数，b 为每元素字节数。该式说明 KV 精度从 FP16 降到 FP8 直接把 b 减半，是解码阶段最直接的显存杠杆；但视觉 token 压缩率对 T_total 的影响是乘性的，压缩率翻倍等价于 KV 占用减半，且不引入量化误差。因此在视觉 token 膨胀的长图像请求上，优先调压缩率而非压 KV 精度，是误差更小的路径。</p>\n<table class=\"mini\"><thead><tr><th>路径</th><th>精度落点</th><th>主要代价</th><th>工程判断</th></tr></thead><tbody><tr><td>视觉编码器卷积/线性</td><td>FP8 或 BF16</td><td>激活显存峰值、缩放元数据带宽</td><td>与分桶粒度联合调，桶细则批小</td></tr><tr><td>视觉归一化/位置编码</td><td>FP16/BF16</td><td>保留高精度副本的显存</td><td>定位与文本阅读的精度底线</td></tr><tr><td>跨模态注入预填</td><td>BF16 累加</td><td>长累加链误差累积</td><td>按桶观测 logits 漂移</td></tr><tr><td>语言模型解码权重</td><td>NVFP4/FP8</td><td>权重带宽、块缩放元数据</td><td>省解码带宽，不省 KV</td></tr><tr><td>KV cache</td><td>FP8</td><td>b 减半、量化误差进注意力</td><td>优先调压缩率再压 KV 精度</td></tr></tbody></table>\n<p>这张账的读法是：每一行对应一个可独立观测的代价项，而不是一个全局精度开关。视觉编码器与语言模型分离部署时，两侧可以走不同精度路径，代价是跨节点传输视觉 token 特征需计入通信开销与失败重试；同卡部署时，编码器峰值显存会挤压 KV cache 空间，精度规划必须给编码器留出峰值余量，否则准入控制估算的并发上限会失真。压缩合并模块的降采样率是唯一同时作用于预填计算、KV 写入与视觉精度的参数，把它与分辨率分桶、精度路径绑定成一组调度参数，才是 Blackwell 上把 Qwen-VL 推理做稳的具体机制。</p>\n\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-19\">十九 · 视觉 token 预算下的精度分层与批内长尾边界</h3>\n<p>把视觉 token 预算当作一等调度参数后，精度策略不能再按“整模型统一量化”处理。视觉编码器前向是串行瓶颈，其特征经压缩合并后直接写入语言模型 KV，跨模态注意力在预填阶段一次性注入、解码阶段只读 KV——这意味着视觉侧的低精度误差不会在解码中被反复摊薄，而是一次性固化进 KV。工程上应把视觉编码器与语言模型分开评估：编码器侧优先保 FP16/BF16 或 FP8，语言侧再考虑 NVFP4；若把 NVFP4 同时压到视觉特征上，压缩合并后的 token 特征动态范围被截断，定位与文本阅读这类依赖细粒度空间信息的任务最先失效。Blackwell 的 tcgen05 与第五代 Tensor Core 支持 FP8/NVFP4 的块缩放矩阵乘，2-SM MMA 通过双 SM 协作提升大 tile 吞吐，TMEM 承担累加器驻留以减少寄存器压力；但累加精度必须与输入精度解耦——FP8 输入配 FP32 累加是底线，NVFP4 输入若用低精度累加，视觉 token 的跨模态注入误差会随压缩率放大。</p>\n<p>KV 计费公式给出失效边界：<div class=\"formula\">$$M_{\\mathrm{KV}}=2\\,L\\,H_{kv}\\,d\\,T_{\\mathrm{total}}\\,b,\\quad T_{\\mathrm{total}}=T_{\\mathrm{vis}}^{\\prime}+T_{\\mathrm{text}}$$</div>其中 $T_{\\mathrm{vis}}^{\\prime}$ 是压缩合并后的视觉 token 数，$b$ 为批大小。压缩率提高会线性压低 $T_{\\mathrm{vis}}^{\\prime}$ 与预填计算，但压缩率与分辨率分桶必须在推理时与训练一致，否则视觉 token 合并破坏定位能力。真正的边界不在单请求，而在批内方差：按请求数切批时，短请求被长图像请求拖慢，首 token 延迟分位由批内最大 $T_{\\mathrm{vis}}^{\\prime}$ 决定，而非均值。按视觉 token 预算切批可压低长尾，代价是桶过细导致批小、编码器延迟摊薄不足；桶过粗则长尾回潮。分辨率分桶粒度因此是精度与吞吐的共同调参点。</p>\n<table class=\"mini\"><thead><tr><th>部署形态</th><th>精度代价</th><th>系统代价</th></tr></thead><tbody><tr><td>编码器与语言模型同卡</td><td>可共享 FP8 路径，但编码器峰值显存挤压 KV</td><td>KV 容量下降，并发上限被编码器峰值锁定</td></tr><tr><td>分离部署</td><td>两侧可独立选 FP8/NVFP4</td><td>跨节点传视觉特征，通信与重试计入首 token 延迟</td></tr><tr><td>高压缩率 + NVFP4</td><td>定位与文本阅读精度需实测</td><td>预填与 KV 写入最省，但桶利用率与批大小受限</td></tr></tbody></table>\n<p>具体例子：一批请求中图像分辨率跨两个数量级，若按请求数切 8 条一批，批内 $T_{\\mathrm{vis}}^{\\prime}$ 方差可达数倍，编码器前向被最长请求主导，短请求的 KV 已写入却要等整批预填完成才进入解码，首 token 延迟分位被拉高。改为按视觉 token 预算切批后，短请求进入小桶快速预填，长请求单独成批，编码器延迟按桶摊薄；代价是桶利用率下降、批次数增多，调度器开销上升。监控需覆盖视觉 token 数分布、批内方差与首 token 延迟分位，准入控制显式估算 $T_{\\mathrm{total}}$ 而非请求数。</p>\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-20\">二十 · 视觉 token 的平方律与 KV 账本的第一性原理</h3>\n<p>Qwen-VL 的推理显存账本必须从视觉 token 的生成方式写起。给定图像高 H、宽 W 与分块边长 P，视觉编码器输出的原始 token 数为：</p>\n<div class=\"formula\">$$T_{\\mathrm{vis}}=\\left\\lceil \\frac{H\\cdot W}{P^{2}}\\right\\rceil,\\quad T_{\\mathrm{total}}=T_{\\mathrm{vis}}^{\\prime}+T_{\\mathrm{text}}$$</div>\n<p>其中 $T_{\\mathrm{vis}}^{\\prime}$ 是经过压缩与合并模块降采样后的视觉 token 数。关键事实是 $T_{\\mathrm{vis}}$ 随分辨率平方增长，而 $T_{\\mathrm{vis}}^{\\prime}$ 由降采样率决定，二者之间的差额就是压缩模块吃掉的那部分预填成本。KV cache 占用按总 token 数线性计费：</p>\n<div class=\"formula\">$$M_{\\mathrm{KV}}=2\\,L\\,H_{kv}\\,d\\,T_{\\mathrm{total}}\\,b$$</div>\n<p>系数 2 来自 K 与 V 两份张量，L 为层数，$H_{kv}$ 为 KV 头数（GQA 下远小于注意力头数），d 为头维，b 为每元素字节数。这个公式的工程含义是：视觉 token 与文本 token 共享同一预算，任何把视觉 token 当作固定开销的准入策略都会在长图像请求上失真。举例而言，同一批内一张高分辨率扫描件与一张缩略图并排，前者贡献的 $T_{\\mathrm{vis}}^{\\prime}$ 可能是后者的数十倍，若调度器只按请求数计费，KV 池会被少数长请求悄悄占满，后续请求在预填阶段才暴露显存不足，表现为首 token 延迟分位突然抬升而非平稳退化。</p>\n<p>在 Blackwell 上，这条平方律还叠加了精度维度的放大效应。B200/B300 的 HBM3e 容量是固定的物理上限，KV cache 的字节数 b 由精度决定：FP8 下 b=1，NVFP4 下每元素约半字节外加缩放因子开销。视觉特征对低精度的敏感度与文本不同，压缩后的视觉 token 若被量化到 NVFP4，定位与文本阅读能力的退化需要单独实测，不能与语言模型侧共用一套量化结论。因此显存规划的第一步不是选精度，而是先把 $T_{\\mathrm{vis}}^{\\prime}$ 的分布统计出来——这是唯一能反推并发上限的量。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-21\">二十一 · 三本账：权重、激活与 KV 的分别核算</h3>\n<p>把显存拆成三本账是做出可复算预算的前提。权重账本是静态的：语言模型参数按精度折算字节数，视觉编码器参数单独成账，二者在分离部署时落在不同设备上，在同卡部署时相加。激活账本是瞬态的但峰值很高：视觉编码器前向的中间特征图与语言模型预填阶段的注意力工作区会同时存在，尤其在跨模态注意力一次性注入时，视觉 token 与文本 token 拼接成统一上下文，预填的注意力矩阵规模按 $T_{\\mathrm{total}}$ 平方增长——这是整条链路里最容易被低估的一项。</p>\n<p>KV 账本则是随并发线性增长的部分，也是容量规划的主约束。三本账的叠加关系决定了部署形态：</p>\n<table class=\"mini\"><thead><tr><th>账本</th><th>随什么增长</th><th>峰值出现时机</th><th>工程手段</th></tr></thead><tbody><tr><td>权重</td><td>参数量 × 精度字节</td><td>常驻</td><td>分精度规划、视觉/语言分离</td></tr><tr><td>激活</td><td>批内 $T_{\\mathrm{total}}$ 与分辨率</td><td>预填注入瞬间</td><td>分桶批处理、限制单批分辨率跨度</td></tr><tr><td>KV</td><td>并发 × $T_{\\mathrm{total}}$ × 层数</td><td>解码稳态</td><td>分页、压缩率、准入控制</td></tr></tbody></table>\n<p>同卡部署的典型失败模式是：视觉编码器在预填前的峰值激活挤压了 KV 池的预留空间，调度器按稳态 KV 估算的并发上限在实际运行时被激活峰值击穿。解法有二，一是分时复用——编码器前向与解码阶段错峰，把编码器激活区在解码期归还给 KV；二是物理分离，把视觉编码器放到独立设备或独立进程，代价是跨节点传输视觉 token 特征，通信开销与失败重试必须计入延迟预算。分离部署还带来一个隐性收益：视觉侧与语言侧可以各自选择精度策略，编码器保留更高精度以守住定位能力，语言侧激进量化以放大 KV 容量。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-22\">二十二 · 分页、压缩、复用与卸载：四种手段的代价结构</h3>\n<p>分页解决的是 KV 池的碎片化。按固定大小 block 分配 KV，逻辑上连续的 token 序列映射到非连续的物理块，长图像请求不再要求一整段连续显存，池的利用率上升。代价是块表查找带来的间接寻址，以及块粒度与 $T_{\\mathrm{total}}$ 不整除时的尾部浪费；块越小碎片越少但元数据开销越大，块越大则长尾请求的内部碎片越明显。对多模态负载，块大小应按视觉 token 压缩后的粒度对齐，否则压缩模块输出的非整数倍 token 会在每个请求尾部留下固定浪费。</p>\n<p>压缩是直接作用于 $T_{\\mathrm{vis}}^{\\prime}$ 的杠杆。降采样率提高一倍，视觉 token 减半，预填计算与 KV 写入同步减半，但跨模态注意力的信息密度下降，定位与文本阅读精度需权衡。这里有一个容易被忽略的耦合：压缩率是在训练时与位置编码、分辨率分桶一起定下的接口，推理时擅自改变合并策略会破坏定位能力，因此压缩率不是运行时可以随意调的旋钮，而是部署前必须与训练侧对齐的常量。真正可调的是分辨率分桶粒度——它决定了进入压缩模块前的 $T_{\\mathrm{vis}}$ 分布。</p>\n<p>复用针对的是前缀相同的请求。多轮对话中系统提示与历史图像不变时，KV 前缀可跨请求共享，只对新追加的文本 token 计费。多模态场景下复用的收益被视觉 token 放大：一张高分辨率图像注入的 KV 若被后续多轮复用，等于把最贵的那段预填摊薄到多次解码。代价是复用判定需要精确的 token 级哈希，图像预处理必须确定性可复现，任何预处理抖动都会让哈希失配、复用失效。</p>\n<p>卸载把冷 KV 换出到主机内存或远端存储，用带宽换容量。HBM3e 的容量是硬约束，卸载的可行性取决于换入换出的带宽是否被解码的访存需求淹没。解码阶段每生成一个 token 要读一遍全部 KV，这个读带宽是稳态瓶颈；若卸载比例过高，换入的 KV 与解码读流争抢同一条 HBM 通道，吞吐会非线性下降。工程判断是：卸载适合长上下文但低并发的场景，不适合高并发短请求——后者应优先靠压缩与分页把 KV 压进 HBM。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-23\">二十三 · 带宽瓶颈的位置：预填看算力，解码看访存</h3>\n<p>多模态推理的带宽瓶颈不在同一个位置。预填阶段把视觉 token 与文本 token 一次性写入 KV，计算密集，瓶颈在张量核心的吞吐与激活显存的容量；解码阶段每步只处理一个新 token，却要读取全部历史 KV，算术强度极低，瓶颈在 HBM 带宽。用 $T_{\\mathrm{total}}$ 与层数估算单步解码的 KV 读取量，再除以 HBM 带宽，就得到单请求解码的访存下界；把这个下界与批内并发相乘，就得到解码吞吐的上界。这条估算解释了为什么视觉 token 膨胀对解码的伤害是双重的：它既抬高单请求的读取量，又压缩可接纳并发，两个因子相乘直接压低 token 吞吐。</p>\n<p>视觉编码器前向是另一处带宽敏感点。编码器处理的是高分辨率特征图，激活体量大、访存模式规整，其延迟主要由分辨率与批大小决定。按分辨率分桶批处理能把编码器的固定开销摊薄，但桶过细会导致每桶批小、桶过粗会导致批内长尾——一张超高分辨率图像拖慢整桶。分桶粒度的调参依据是视觉 token 数的分布分位数，而不是图像尺寸的均匀切分。分离部署时，视觉特征跨节点传输的带宽开销要单独计入首 token 延迟预算：传输量正比于 $T_{\\mathrm{vis}}^{\\prime}$ 与特征维度，压缩率越高传输越省，这构成压缩的第二个收益来源。</p>\n<p>Blackwell 的 HBM3e 容量与带宽是容量规划的两个独立约束，不能混为一谈。容量决定并发上限，带宽决定解码吞吐上限，二者在不同负载形态下轮流成为瓶颈：高并发短文本时容量先撞墙，低并发长图像时带宽先撞墙。容量规划必须同时给出两个数字，并在监控中分别跟踪 KV 池占用率与解码阶段的带宽利用率。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-24\">二十四 · 一个可复算的显存预算</h3>\n<p>下面给出一个可代入实际参数复算的预算框架，不依赖任何未给出的实验数字。设语言模型层数 L、KV 头数 $H_{kv}$、头维 d、精度字节 b，视觉编码器参数与激活单独成账，单请求总 token 数为 $T_{\\mathrm{total}}=T_{\\mathrm{vis}}^{\\prime}+T_{\\mathrm{text}}$。单请求 KV 字节为 $2LH_{kv}d\\,T_{\\mathrm{total}}b$，设备可用 KV 池容量为 HBM 容量减去权重、激活预留与运行时开销后的余量，则可接纳并发为：</p>\n<div class=\"formula\">$$N_{\\mathrm{conc}}=\\left\\lfloor \\frac{M_{\\mathrm{HBM}}-M_{\\mathrm{weight}}-M_{\\mathrm{act}}^{\\mathrm{peak}}-M_{\\mathrm{reserve}}}{2LH_{kv}d\\,\\bar{T}_{\\mathrm{total}}\\,b}\\right\\rfloor$$</div>\n<p>其中 $\\bar{T}_{\\mathrm{total}}$ 应取批内总 token 数的期望而非最大值，否则预算过于保守；但准入控制必须按单请求的 $T_{\\mathrm{total}}$ 逐个校验，防止长图像请求突破上限。复算步骤是：先统计视觉 token 数分布得到 $\\bar{T}_{\\mathrm{vis}}^{\\prime}$，再叠加文本长度分布得到 $\\bar{T}_{\\mathrm{total}}$，代入公式得到并发上限，最后用解码带宽下界校验吞吐是否满足 SLO。若并发上限满足而吞吐不满足，说明瓶颈在带宽而非容量，应优先提高压缩率或降低精度字节 b；若容量先撞墙，应优先分页与复用。</p>\n<p>一个具体例子：同一设备上，若把视觉压缩率提高一档使 $T_{\\mathrm{vis}}^{\\prime}$ 减半，单请求 KV 字节近似减半（文本部分不变），并发上限近似翻倍，同时预填的注意力计算按 $T_{\\mathrm{total}}$ 平方下降、跨节点传输量减半。代价是定位与文本阅读精度需实测确认。这个权衡的方向是明确的：在多模态负载中，压缩率是同时作用于容量、带宽与传输三项成本的单一旋钮，其精度代价必须用定位任务的实测来定价，而不能用通用语言任务的困惑度替代。</p>\n<p>预算框架的落地要求监控覆盖三个量：视觉 token 数分布的分位数、批内 $T_{\\mathrm{total}}$ 方差、以及 KV 池占用率与解码带宽利用率的比值。前两者决定分桶粒度与切批策略，后者决定扩容方向是加容量还是加带宽。把这三个量接入准入控制，长图像请求在进入预填前就被估算并拒绝或排队，而不是在预填中途触发显存不足——这是把视觉 token 预算从事后统计变成事前调度的关键一步。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-25\">二十五 · 视觉 token 预算的失效边界与同卡部署的显存挤压</h3>\n<p>把视觉 token 预算当作准入控制的硬门槛，前提是压缩率在推理时保持恒定。一旦分桶粒度过粗，同一桶内高分辨率图像经合并后仍可能溢出预算，此时 <span class=\"formula\">$$T_{\\mathrm{vis}}^{\\prime}$$</span> 不再是常数，KV 账本随之失真：<span class=\"formula\">$$M_{\\mathrm{KV}}=2\\,L\\,H_{kv}\\,d\\,(T_{\\mathrm{vis}}^{\\prime}+T_{\\mathrm{text}})\\,b$$</span> 中的 <span class=\"formula\">$$T_{\\mathrm{vis}}^{\\prime}$$</span> 若按桶上限估算，短请求被过度计费、长请求被低估，准入控制要么拒绝本可接纳的并发，要么放行后触发显存回收抖动。工程判断是：分桶按压缩后 token 数的分位而非原始分辨率切，桶内方差超过阈值即拆桶，代价是桶利用率下降、编码器批变小、串行瓶颈更难摊薄。</p>\n<p>更隐蔽的失效来自视觉编码器与语言模型同卡部署。编码器前向的激活峰值与 KV cache 争抢同一块 HBM3e，编码器阶段 KV 尚未写入但显存已被激活占住，解码阶段编码器空闲却仍持有权重与 workspace。两者峰值不重叠，容量却按峰值之和规划，直接压缩可接纳并发。分离部署解耦了这一冲突，代价是视觉特征跨节点传输，NVLink 5 域内可摊薄，跨节点则需把特征字节数计入首 token 延迟预算，并承担失败重试带来的尾延迟。</p>\n<table class=\"mini\"><thead><tr><th>部署形态</th><th>显存冲突</th><th>主要代价</th></tr></thead><tbody><tr><td>同卡</td><td>编码器激活挤压 KV</td><td>并发上限下降，需分时调度</td></tr><tr><td>分离</td><td>无</td><td>特征传输与重试开销</td></tr></tbody></table>\n<p>压缩率本身是精度与显存的交换。跨模态注意力在预填阶段一次性注入、解码只读 KV，压缩率提高直接减少预填计算与 KV 写入，但合并降采样会稀释定位与文本阅读所需的空间细节；材料未给出 NVFP4/FP8 下视觉特征的精度代价，视觉侧对低精度更敏感的可能性必须实测而非默认沿用语言侧量化策略。可复算的边界是：给定 <span class=\"formula\">$$M_{\\mathrm{KV}}$$</span> 上限与 <span class=\"formula\">$$T_{\\mathrm{text}}$$</span> 分布，反解 <span class=\"formula\">$$T_{\\mathrm{vis}}^{\\prime}$$</span> 的可接纳上限，再与压缩率下限取交集，交集为空即说明该显存档位下长图像请求必须走分离部署或降分辨率准入。</p>\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-26\">二十六 · 视觉 token 预算作为切批的第一性变量</h3>\n<p>Qwen-VL 推理侧最容易被低估的事实是：批调度的基本单位不是请求，而是 token。视觉 token 数按 <span class=\"formula-inline\">$$T_{\\mathrm{vis}}=\\left\\lceil \\frac{H\\cdot W}{P^{2}}\\right\\rceil$$</span> 随分辨率平方增长，而压缩合并模块的降采样率把它折算成注入语言模型的 <span class=\"formula-inline\">$$T_{\\mathrm{vis}}^{\\prime}$$</span>。真正进入 KV 计费的是 <span class=\"formula-inline\">$$T_{\\mathrm{total}}=T_{\\mathrm{vis}}^{\\prime}+T_{\\mathrm{text}}$$</span>，即 <span class=\"formula-inline\">$$M_{\\mathrm{KV}}=2\\,L\\,H_{kv}\\,d\\,T_{\\mathrm{total}}\\,b$$</span>。因此调度器在准入阶段就必须把每张图折算成一个 token 预算数字，而不是等到预填阶段才发现显存不够。工程上的做法是：请求到达时读取图像尺寸与文本长度，先算 <span class=\"formula-inline\">$$T_{\\mathrm{vis}}^{\\prime}$$</span> 的期望值，再与当前批已占用的 token 预算相加，超过阈值就另起一批或排队。按请求数切批在这里是错误抽象——两张 1024×1024 与十张 224×224 的请求数相同，token 预算相差一个量级，混在一批里短请求必然被长请求拖住预填与首 token 延迟。</p>\n<p>代价体现在三个方向。显存上，KV 预算被长图像请求一次性吃掉，可接纳并发被压缩；延迟上，批内最长请求决定整批的预填完成时刻，短请求的 TTFT 分位被拉高；吞吐上，若批内 token 方差大，解码阶段的每步有效 token 利用率下降，因为长请求解码步数多、短请求早已结束却仍占着批槽位直到整批回收。具体例子：一个批里放入一张高分辨率文档图（压缩后仍有可观视觉 token）与若干短文本问答，前者的预填计算量主导整批，后者的首 token 要等前者视觉编码与注入完成才释放，尾延迟直接由最长请求定义。切批策略应改为按 <span class=\"formula-inline\">$$T_{\\mathrm{total}}$$</span> 的预算装箱，允许批内请求数不等，换取批内长度方差收敛。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-27\">二十七 · 连续批处理在视觉侧的两个断点</h3>\n<p>连续批处理（continuous batching）在纯文本 LLM 上成熟，是因为解码步是天然同步点：每步结束即可回收完成的序列、插入新序列。多模态请求把这条流水线切出两个断点。第一个断点是视觉编码器前向——它是一次性的大计算块，不能像解码那样按步插入，新到的图像请求必须等编码器完成一个桶的批前向才能进入语言模型侧。第二个断点是跨模态注入：视觉 token 在预填阶段一次性写入 KV，写入之后解码阶段只读 KV，这意味着一个请求的“可解码”状态取决于预填是否完成，而预填的耗时由视觉 token 数决定。连续批处理若只在语言模型侧做，会把视觉编码器变成批外的串行瓶颈：语言侧批槽位空转等待编码器输出。</p>\n<p>可行的机制是把两级批处理解耦：视觉侧维护按分辨率分桶的待处理队列，桶内攒够批或超时就前向一次，输出压缩合并后的视觉特征放入特征缓冲；语言侧调度器从特征缓冲取已就绪的请求做预填与解码的连续批处理。伪代码思路是：<em>while 有新请求：按 (H,W) 落入桶；若桶内 token 预算达阈值或等待超时，对该桶做编码器批前向并压缩合并，产出 (req_id, vis_tokens) 写入就绪队列；语言侧每步从就绪队列取请求填充预填槽，预填完成后转入解码集合，解码集合每步回收完成序列</em>。代价是特征缓冲占用显存与就绪队列的调度延迟：桶攒批的等待时间直接加到 TTFT 上，桶阈值设得越高，编码器利用率越好但尾延迟越差。工程判断是给桶等待设一个硬超时，把编码器批大小与 TTFT 预算绑定，而不是追求编码器满批。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-28\">二十八 · Chunked prefill 与视觉 token 的注入粒度</h3>\n<p>Chunked prefill 的作用是把长预填切成若干块，与解码步交错执行，避免一个超长预填把整批解码卡住若干毫秒级步长。对 Qwen-VL 而言，切分点的选择比文本模型更讲究：视觉 token 与文本 token 在预填阶段拼接成统一上下文，跨模态注意力一次性注入，因此不能简单按固定 token 数切——切在视觉 token 中间会破坏一次注入的语义完整性，且视觉特征在压缩合并后是一个整体块。合理做法是以视觉 token 块为最小不可分单元，在其前后按文本 token 预算切分：预填序列被切成 [文本前缀 | 视觉块 | 文本后缀] 的若干 chunk，视觉块整体作为一个 chunk 或与相邻文本合并，保证跨模态注意力在一个 chunk 内完成。</p>\n<p>代价是预填 chunk 数增加带来的额外 kernel 启动与 KV 写入次数，以及 chunk 边界处的注意力掩码处理开销。收益是解码步的间隔变得可预测：没有 chunked prefill 时，一个高分辨率图像请求的预填可能占据数个解码步的时间，同批其他请求的 token 间延迟（ITL）出现尖峰；启用后，每个解码步之间插入一个预填 chunk，ITL 方差收敛。具体例子：批内已有若干正在解码的短请求，此时到一个文档阅读请求，其视觉 token 块较大；若不切分，这些短请求的 ITL 被这一个预填拉长；若把视觉块与文本后缀切成两块交错插入，短请求的 ITL 尖峰被削平，代价是该文档请求自身的 TTFT 略微后移。这是典型的时延内部再分配：用长请求的 TTFT 换短请求的 ITL 尾部分位。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-29\">二十九 · 优先级、抢占与 KV 回收的次序</h3>\n<p>多模态负载的优先级不是按请求到达顺序排的，而是按“已投入的不可回收成本”排。视觉编码器前向与压缩合并一旦完成，视觉特征已经占了显存与计算；此时若因 KV 预算不足而抢占该请求，重算代价包括重新编码图像，远高于纯文本请求的重新预填。因此抢占策略应优先选择“重算便宜”的受害者：纯文本、短上下文、视觉特征尚未生成的请求。机制上可给每个请求打两个标记——<em>vis_ready</em>（视觉特征是否已产出并驻留）与 <em>kv_footprint</em>（当前 KV 占用 token 数）；KV 不足时按 <em>kv_footprint</em> 降序、<em>vis_ready</em> 为真者后选，回收其 KV 槽位并保留视觉特征缓冲，待预算恢复后仅重做预填注入而不重跑编码器。</p>\n<p>代价是特征缓冲的常驻显存：被抢占请求的视觉特征若保留，等于用显存换重算；若不保留，抢占即意味着重跑编码器，尾延迟出现二次尖峰。工程上需要给特征缓冲设上限，超过上限时按最久未使用淘汰，并接受重编码代价。另一个代价是抢占引起的解码批重组，批内序列数变化会导致 kernel 形状变化与利用率抖动。具体例子：一个高优先级交互请求到达而 KV 预算已满，调度器抢占两个低优先级长文本请求的 KV，保留其视觉特征；交互请求完成预填后进入解码，被抢占请求在后续步重新预填，其 TTFT 被推后但视觉编码未重跑——这是把抢占代价从“编码器重跑”降到“预填重做”的具体收益。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-30\">三十 · 分离式预填/解码与视觉编码器的三段部署</h3>\n<p>把视觉编码器、预填、解码拆成三个资源池，是 Blackwell 上压尾延迟的结构性手段。视觉编码器是计算密集且批内长度相对整齐（同桶同分辨率）的负载，适合独立卡组做分桶批前向；预填是带宽与计算混合、受视觉 token 数主导的负载；解码是显存带宽主导、批越大越划算的负载。三者混在同一组卡上时，编码器峰值显存会挤压 KV cache 空间，预填的长计算块会打断解码的稳定步进。分离部署后，视觉特征经节点间链路传到预填池，预填产出的 KV 再传到解码池——代价是两次跨节点传输与失败重试，收益是每段都能用自己的批策略与精度策略。</p>\n<p>传输代价必须计入 SLO：视觉特征的大小与 <span class=\"formula-inline\">$$T_{\\mathrm{vis}}^{\\prime}$$</span> 成正比，压缩率越高传输越省，但压缩率同时影响定位与文本阅读精度，这是分离部署下压缩率选择的额外约束。预填到解码的 KV 传输量按 <span class=\"formula-inline\">$$M_{\\mathrm{KV}}$$</span> 计，长图像请求的 KV 搬运会占用链路带宽，若与解码池的批调度不同步，会出现解码池等 KV 的空转。工程判断是：分离部署的收益在负载异构、SLO 分层明确时成立；若请求以短文本为主、图像分辨率集中，同卡部署加分辨率分桶反而通信开销更小。具体例子：交互式图文问答与批量文档阅读混跑时，前者要求低 TTFT、后者要求高吞吐，分离后交互请求走小批低延迟路径、文档请求走大批高吞吐路径，两条路径的批参数互不干扰。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-31\">三十一 · 尾延迟的度量与分桶粒度的调参闭环</h3>\n<p>压尾延迟的前提是度量对象正确。多模态请求的 TTFT 应拆成三段分别监控：编码器排队与等待桶攒批的时间、编码器前向与压缩合并时间、预填注入时间。只监控端到端 TTFT 会把编码器排队与预填混在一起，无法判断该调桶阈值还是该调 chunk 大小。ITL 则要按批内请求的视觉 token 数分层统计，因为长图像请求的预填块会周期性插入解码步，其 ITL 分布与纯文本请求不同。分桶粒度的调参闭环是：按视觉 token 分布统计各桶的到达率与桶内方差，桶过细导致批小、编码器利用率低、TTFT 中位数上升；桶过粗导致桶内长短混杂、尾部分位恶化。调参目标是使每个桶的批内 token 方差低于阈值，同时桶的到达率足以在超时前攒够批。</p>\n<p>代价是监控本身的开销与分桶表的热更新：桶边界变化会改变编码器批形状，进而影响已编译 kernel 的复用。工程上把桶边界做成有限集合（按常见分辨率档位），避免连续分桶导致 kernel 反复重编译。具体例子：文档阅读请求集中在高分辨率档、交互请求集中在低分辨率档，若两档合并为一个桶，交互请求的 TTFT 被文档请求的编码器批前向拖慢；拆成两桶后交互桶批小但延迟低，文档桶批大但吞吐高，两桶各自设超时阈值——这就是用分桶粒度把时延与吞吐的取舍显式化，而不是让调度器在混合批里被动承受方差。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-32\">三十二 · 视觉 token 预算切批的边界与失效条件</h3>\n<p>把视觉 token 数当作一等调度参数，落地形态是按 token 预算切批而非按请求数切批：设批内预算为 <span class=\"inline-formula\">$B_{\\mathrm{tok}}$</span>，请求 <span class=\"inline-formula\">$i$</span> 的视觉 token 为 <span class=\"inline-formula\">$T_{\\mathrm{vis},i}^{\\prime}$</span>、文本 token 为 <span class=\"inline-formula\">$T_{\\mathrm{text},i}$</span>，则准入条件为 <span class=\"inline-formula\">$\\sum_i (T_{\\mathrm{vis},i}^{\\prime}+T_{\\mathrm{text},i})\\le B_{\\mathrm{tok}}$</span>，且需同时满足 <span class=\"inline-formula\">$M_{\\mathrm{KV}}=2LH_{kv}d\\,T_{\\mathrm{total}}b$</span> 的显存档位约束。这一策略的边界很明确：当桶内视觉 token 方差本身很大时，预算切批只能限制批的总量，无法消除单请求内部的预填长尾——一张高分辨率图压缩后仍占去预算的大半，同批其余请求只能拿到很小的解码窗口，首 token 延迟分位被单请求主导。失效条件是压缩率与分辨率分桶粒度不匹配：桶过粗则批内方差压不下来，桶过细则每桶请求稀疏、编码器批前向摊薄不了延迟，桶利用率与长尾之间没有免费的解。</p>\n<p>视觉编码器与语言模型同卡部署是另一类硬边界。编码器前向的峰值显存与 KV cache 争同一块 HBM，编码器批越大峰值越高，KV 可接纳并发就被压得越低；此时按 token 预算切批反而会放大抖动，因为编码器批大小与语言侧批大小被耦合在同一调度决策里。工程上的判断是：只要编码器峰值显存占用的增量超过 KV 预留的安全水位，就应改为分时执行或直接分离部署，把编码器按分辨率分桶批处理、语言侧独立管理 KV。分离部署解耦了两类负载的批调度与精度策略，代价是跨节点传输视觉 token 特征，通信开销与失败重试必须计入首 token 延迟预算，NIXL 这类传输层的作用正在于此。</p>\n<p>跨模态注意力在预填阶段一次性注入、解码阶段只读 KV，这决定了压缩率是预填成本与 KV 写入的唯一杠杆，也决定了它与定位、文本阅读精度之间的权衡不可回避：压缩率越高，预填计算与 KV 占用越省，但视觉 token 合并会破坏细粒度空间信息。因此压缩率不能作为纯吞吐参数调节，必须与训练时的位置编码和分辨率分桶保持一致，否则合并后的 token 在语言模型侧失去可解释的空间对应。下表给出三类调度决策的代价对照，均为定性判断，材料未给出具体数字。</p>\n<table class=\"mini\"><thead><tr><th>决策</th><th>收益</th><th>系统代价</th><th>失效条件</th></tr></thead><tbody><tr><td>按视觉 token 预算切批</td><td>压低批内长尾与首 token 延迟方差</td><td>批利用率随方差上升而下降</td><td>单请求占预算过半，解码窗口被挤压</td></tr><tr><td>编码器分桶批处理</td><td>摊薄串行编码器延迟</td><td>桶过细导致批小、桶过粗导致长尾</td><td>分辨率分布长尾，桶利用率低</td></tr><tr><td>视觉/语言分离部署</td><td>解耦批调度与精度策略</td><td>跨节点特征传输与重试开销</td><td>通信预算吃紧，首 token 延迟反升</td></tr></tbody></table>\n<p>尾延迟的压缩最终落在准入控制上：KV 按总 token 数计费，视觉与文本共享同一预算，长图像请求会显著压缩可接纳并发，若不显式估算视觉 token 就放行，并发上限会被静默突破。可操作的做法是把视觉 token 数分布、批内方差与首 token 延迟分位纳入监控，用分位而非均值驱动分桶粒度与预算调参；当分位延迟的抬升来自批内方差而非编码器本身时，调桶；当抬升来自编码器串行段时，调批大小或分离部署。优先级与抢占在此只应作用于解码阶段的 KV 回收，不应作用于已注入的视觉 token——预填一旦完成，视觉 KV 的重算代价远高于文本。</p>\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-33\">三十三 · 切分维度与视觉负载的耦合</h3>\n<p>在 Blackwell 上部署 Qwen-VL，并行切分不是先选拓扑再塞负载，而是由视觉 token 数随分辨率平方增长这一事实反向决定。TP 切分语言模型的注意力与 FFN 权重，每层需要两次 All-Reduce（注意力输出与 FFN 下投影后），通信量与隐藏维度和批内 token 数成正比；PP 把层段放到不同 GPU，边界处只传激活，通信量小但引入流水气泡，气泡大小取决于微批数与段数之比；DP 复制整模型、切分请求，除梯度场景外推理侧几乎无集合通信，代价落在 KV cache 副本与权重副本的显存上；EP 用于 MoE 语言模型，路由后 token 被打散到专家所在卡，需要 All-to-All。Qwen-VL 的特殊性在于视觉编码器前向是串行瓶颈且峰值显存可观：若编码器与语言模型同卡，编码器激活峰值会挤压 KV cache 空间，因此工程上更倾向把视觉侧按分辨率分桶独立部署，语言侧再按 TP/PP 切分，两侧之间只传压缩合并后的视觉 token 特征。</p>\n<p>切分选择可用一条粗略的通信-计算比来判断。设单层计算量为 $C$、集合通信量为 $V$、互联带宽为 $B$，则通信占比近似为</p>\n<div class=\"formula\">$$\\rho=\\frac{V}{B}\\Big/\\Big(\\frac{C}{F}\\Big)=\\frac{V\\cdot F}{C\\cdot B}$$</div>\n<p>其中 $F$ 为算力。$\\rho$ 随批内 token 数增大而下降——这是大 batch 掩盖 TP 通信的根本原因；但多模态批内 token 数由图像分辨率主导，短请求批的 $\\rho$ 会显著偏高。具体例子：一个以文本为主、图像为小图的请求批，视觉 token 经压缩后仅占少量，语言侧预填 token 数低，TP=8 的两次 All-Reduce 在 NVLink 5 上虽快，却无法被有限的计算量摊薄，此时增大 TP 反而拉高首 token 延迟；反之长图像请求批 token 数高，TP 通信被充分掩盖，扩 TP 能降单卡显存、提并发。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-34\">三十四 · NVLink 5 与 NVSwitch 的带宽账</h3>\n<p>GB200/GB300 NVL72 机柜内 GPU 通过 NVLink 5 与 NVSwitch 全互联，单 GPU 对外聚合带宽远高于 PCIe，且 All-to-All 在机柜内是一跳而非多跳。这直接改变 EP 与 TP 的可行域：EP 的 All-to-All 若跨机柜走 InfiniBand，延迟与带宽都会掉一个档位，MoE 路由的负载不均会被放大成尾延迟；TP 的 All-Reduce 若限制在单机柜内，则 TP 度数与机柜拓扑绑定。工程判断是：把通信最密集的维度（TP 的每层 All-Reduce、EP 的每层 All-to-All）压在 NVLink 域内，把通信稀疏的维度（PP 的段边界、DP 的请求分发）放到跨节点链路上。</p>\n<p>代价要按每次前向的通信次数乘出来。以 TP 为例，$L$ 层、每层两次 All-Reduce、每次传输 $T_{\\mathrm{total}}\\cdot d\\cdot b$ 字节（$d$ 为隐藏维、$b$ 为字节宽），单请求预填的 TP 通信量为</p>\n<div class=\"formula\">$$V_{\\mathrm{TP}}\\approx 2\\,L\\cdot T_{\\mathrm{total}}\\cdot d\\cdot b\\cdot\\frac{\\mathrm{TP}-1}{\\mathrm{TP}}$$</div>\n<p>Ring 实现的传输量随 TP 增大趋近饱和，而延迟随跳数线性增长，因此 TP 超过单机柜规模后收益递减。具体例子：视觉 token 压缩率提高使 $T_{\\mathrm{total}}$ 下降，$V_{\\mathrm{TP}}$ 同比线性下降——压缩不只是省 KV，也直接省 TP 通信，这是多模态场景里压缩与并行拓扑必须联合调参的原因。反过来，若为了定位与文本阅读精度保留高分辨率、低压缩率，$T_{\\mathrm{total}}$ 抬升会同时推高 KV 显存与 TP 通信，两个成本同向恶化。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-35\">三十五 · All-Reduce 与 All-to-All 的瓶颈判据</h3>\n<p>All-Reduce 的瓶颈判据是“计算能否覆盖通信”：预填阶段矩阵乘的算术强度高，大 token 数下通信易被掩盖；解码阶段每步只处理批内少量 token，算术强度骤降，TP 的 All-Reduce 变成每步固定开销，直接体现为解码 token 间隔（ITL）的下限。多模态请求的解码阶段虽只读 KV，但视觉 token 已在预填写入，KV 读取带宽与 TP 通信叠加，长上下文请求的 ITL 会被这两项共同抬高。All-to-All 的瓶颈判据是“负载均衡”：MoE 路由若因视觉 token 分布偏移导致专家负载倾斜，最热专家所在卡的 All-to-All 成为木桶短板，此时增加 EP 度数不解决问题，需在路由侧做容量因子约束或把热专家复制。</p>\n<p>一个可操作的判据是通信时间占比阈值：当单层通信时间超过计算时间的一半，扩并行度对吞吐的边际收益转负。用伪代码表达调度器的决策思路：</p>\n<ul>\n<li>读取批内 $T_{\\mathrm{total}}$ 分布与分辨率桶标签；</li>\n<li>估算该批在候选 TP 度数下的 $\\rho$，若 $\\rho$ 超过阈值则降 TP、改走 PP 或增大批；</li>\n<li>对 MoE 层估算专家负载方差，超阈值则触发专家复制或路由惩罚；</li>\n<li>把视觉编码器批与语言侧批解耦，编码器批不参与 TP 通信估算。</li>\n</ul>\n<p>具体例子：解码阶段批内仅数十个 token 时，TP=8 的每步 All-Reduce 延迟可能主导 ITL；此时把 TP 降到 4、用多出来的卡扩 DP 承接更多并发请求，端到端吞吐反而上升，代价是单请求权重显存翻倍、可接纳并发受 KV 预算约束——这正是并行拓扑与准入控制必须联立求解的地方。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-36\">三十六 · NIXL 传输与分离式部署的通信成本</h3>\n<p>视觉编码器与语言模型分离部署时，压缩合并后的视觉 token 特征需从编码器节点传到语言模型节点，NIXL 提供点对点、低开销的显存到显存传输抽象，可绕过主机内存拷贝、直接注册显存缓冲做 RDMA 或 NVLink 传输。这条路径的成本要计入首 token 延迟：传输量正比于压缩后视觉 token 数乘特征维度乘字节宽，传输延迟包含建链、注册与重试。工程上应把视觉特征缓冲预注册、按分辨率桶预分配，避免每请求动态注册带来的固定开销；失败重试要计入 SLO 预算，否则尾延迟分位会被重传拉高。</p>\n<p>分离部署的收益是解耦两类负载的批调度与精度策略：编码器可按分辨率桶大批量摊薄串行延迟，语言侧专注 KV 管理与解码；代价是跨节点传输与两侧批节奏不匹配——编码器批完成时间与语言侧预填窗口若不对齐，特征会在缓冲里排队，等效于把编码器延迟转成了排队延迟。具体例子：高分辨率桶的编码器批耗时远高于低分辨率桶，若语言侧按统一节奏拉取特征，低分辨率请求会被高分辨率桶的传输阻塞；应按桶维护独立特征队列并让语言侧调度器按队列水位拉取。传输量与 KV 占用的关系是：压缩率越高，传输量与 KV 写入同比例下降，分离部署的通信代价与显存代价同向受益，因此压缩率是分离式部署的第一调参量。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-37\">三十七 · 通信何时成为瓶颈的工程判断</h3>\n<p>把前述判据收敛成三条可监控的信号。第一，批内 $T_{\\mathrm{total}}$ 方差：方差大意味着批内长尾，短请求的 TP 通信无法被自身计算掩盖，表现为首 token 延迟分位拉高，应按视觉 token 预算切批而非按请求数。第二，解码阶段 ITL 与 TP 度数的关系曲线：若 ITL 随 TP 增大不降反升，说明已越过通信主导区，应降 TP 扩 DP。第三，跨节点传输队列水位：分离部署下队列持续非空说明编码器吞吐不足或桶粒度不当，需调桶粒度或增编码器副本，而不是加语言侧并行度。</p>\n<p>显存侧的耦合不能忽略：TP 增大降低单卡权重与 KV 分片，但 All-Reduce 缓冲与通信库工作区占用上升；PP 增大降低单卡层数却要求段间激活缓冲；EP 增大降低单卡专家权重但 All-to-All 缓冲随度数增长。多模态场景里 KV cache 按 $T_{\\mathrm{total}}$ 计费，视觉 token 与文本 token 共享预算，长图像请求会压缩可接纳并发，准入控制必须显式估算 $M_{\\mathrm{KV}}$ 后再决定该请求进入哪个并行拓扑的副本——把并行度、压缩率、桶粒度三者放进同一个容量规划循环，而不是分别调优，才是 Blackwell 上 Qwen-VL 推理不出现“加卡反而变慢”的前提。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-38\">三十八 · 视觉侧与语言侧分离部署时的通信边界</h3>\n<p>把视觉编码器与语言模型拆到不同 GPU 或不同节点，是 Qwen-VL 在 Blackwell 上绕开“编码器峰值显存挤压 KV cache”的直接手段，但它把问题从显存搬到了链路。视觉编码器输出的是压缩合并后的视觉 token 特征张量，形状约为 [T′_vis, d]，以 BF16 计每 token 约 2d 字节；一次预填要把这批特征经 NVLink 5 或跨节点 fabric 送到语言侧，再在预填阶段一次性写入 KV。传输量随 T′_vis 线性增长，而 T′_vis 又随分辨率平方增长，因此分离部署的通信代价本质上是被压缩率调制过的分辨率函数。在 GB200 NVL72 机柜内，NVLink 5 与 NVSwitch 让同域 All-to-All 的带宽相对充裕，视觉特征传输通常不是瓶颈；一旦视觉桶与语言桶落在不同机柜、走的是带宽低一个档次的跨域链路，单请求的视觉特征搬运就会进入首 token 延迟的关键路径。工程判断很直接：分离部署只在视觉 token 预算被压到较小、且两侧同处一个 NVLink 域时才划算；跨域分离必须把视觉特征传输时间显式计入 SLO 预算，否则首 token 延迟分位会被链路抖动主导。</p>\n<p>并行切分方式决定了通信原语，也决定了哪种通信先成为瓶颈。语言侧 TP 每层两次 All-Reduce，单次通信量约 2·T_total·d·b 字节，随批内总 token 数线性增长，因此 TP 的通信瓶颈出现在大 batch、长上下文预填阶段；EP 则把 MoE 专家分散，每层一次 All-to-All，通信量随被路由 token 数与专家并行度增长，且 All-to-All 对链路的不对称拥塞更敏感，尾延迟比 All-Reduce 更难压。PP 的通信量小但引入流水线气泡，气泡占比近似 (P−1)/(m+P−1)，m 为微批数，多模态批内长度不齐会放大微批间不均衡，使气泡实际大于该式估计。DP 本身不产生集合通信，但在 KV cache 按总 token 数计费的前提下，DP 副本各自持有独立 KV，显存复制代价乘以副本数。把这四者放在一张表里看边界：</p>\n<table class=\"mini\"><thead><tr><th>切分</th><th>主要原语</th><th>通信量随什么增长</th><th>先失效的场景</th></tr></thead><tbody><tr><td>TP</td><td>All-Reduce</td><td>批内总 token 数</td><td>长上下文预填、大 batch</td></tr><tr><td>EP</td><td>All-to-All</td><td>路由 token 数 × 专家并行度</td><td>专家负载不均、跨域链路</td></tr><tr><td>PP</td><td>点对点激活</td><td>微批数</td><td>批内长度方差大、微批不足</td></tr><tr><td>DP</td><td>无集合通信</td><td>KV 副本数</td><td>显存档位不足</td></tr></tbody></table>\n<p>通信成为瓶颈的判据可以写成一个可计算的比较：设单层计算时间为 t_comp、单次集合通信时间为 t_comm，则计算通信比 γ = t_comp / t_comm，当 γ 降到 1 附近时该层由通信主导。对 TP 的 All-Reduce，t_comm 近似为 2·(N−1)/N · S / B_link，S 为该层激活字节数，N 为 TP 度，B_link 为有效链路带宽；S 随 T_total 增长而 B_link 固定，所以 γ 随上下文长度单调下降，长图像请求正是把 γ 压到 1 以下的那类负载。这也是为什么按视觉 token 预算切批不只是调度问题：它同时限制了单批的 S，把 γ 维持在计算主导区间。NIXL 在这里的角色是让 KV 与视觉特征的跨节点搬运绕开框架层的序列化开销，以点对点传输直接对接显存，降低分离式预填/解码场景下的传输启动延迟；但它不改变带宽上限，链路带宽仍是硬约束。失效条件因此清晰：当视觉 token 压缩率不足、分辨率分桶过粗导致单批 S 过大，或 EP 的 All-to-All 跨出 NVLink 域时，通信开销会从可摊薄的后台成本变成首 token 延迟的主项，此时应优先收紧视觉 token 预算与分桶粒度，而不是继续加并行度。</p>\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-39\">三十九 · 精度塌陷：视觉侧先崩，语言侧后崩</h3>\n<p>Qwen-VL 的推理链路里，精度塌陷不是单点事件，而是沿“视觉编码器 → 压缩合并 → 跨模态注入 → 自回归解码”逐段传播的。NVFP4/FP8 落到视觉编码器时，最先受损的往往不是图文问答的语义，而是定位与文本阅读：视觉特征被降采样到低精度后，细粒度空间关系在压缩合并阶段被进一步抹平，跨模态注意力拿到的视觉 token 已经丢失了位置可分性，语言模型再强也补不回来。工程上要区分两类塌陷：一类是“可观测塌陷”，输出开始出现坐标漂移、OCR 漏字、框选偏移；另一类是“静默降级”，答案仍然通顺，但定位精度和文本阅读召回在分位统计上缓慢下滑，单条请求看不出来。</p>\n<p>诊断机制上，把视觉 token 的注入质量做成可回归的探针：固定一小批带定位标注与文本阅读的请求，在每次量化配置变更后跑同一组探针，比较跨模态注意力注入前后的视觉 token 范数分布与位置编码一致性。位置编码与分辨率分桶必须在推理时与训练一致，否则视觉 token 合并会破坏定位与文本阅读能力——这条接口约束是精度塌陷最常见的隐性来源，分桶边界改动、压缩率改动都会触发。</p>\n<div class=\"formula\">$$\\Delta_{\\mathrm{loc}}=\\frac{1}{N}\\sum_{i}\\left\\|\\hat{b}_i-b_i\\right\\|_1,\\quad \\Delta_{\\mathrm{ocr}}=1-\\frac{\\text{正确字符数}}{\\text{总字符数}}$$</div>\n<p>代价落在吞吐与显存上：把视觉编码器留在 FP8、语言模型走 NVFP4 的混合精度方案，能省下语言侧权重与 KV 的显存，但视觉侧精度不降意味着编码器激活显存不缩，同卡部署时仍会挤压 KV cache 空间。具体例子：一批高分辨率文档图请求，压缩率调高后 KV 占用下降、并发上升，但 OCR 探针的字符召回下滑，此时应回滚压缩率而非回滚量化，因为塌陷源在压缩合并而非数值精度。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-40\">四十 · OOM：峰值不在解码，在编码器与预填的交界</h3>\n<p>多模态推理的 OOM 很少发生在解码阶段，而是发生在视觉编码器前向峰值与预填阶段 KV 写入叠加的瞬间。视觉 token 数随分辨率平方增长，编码器激活显存按桶内最大分辨率计，而预填阶段要把压缩后的视觉 token 与文本 token 拼成统一上下文写入 KV，两者在同一时刻争抢显存。同卡部署时，编码器峰值显存会挤压 KV cache，表现为“批还没满就 OOM”，调度器却以为并发上限还有余量。</p>\n<p>定位手段是把显存占用拆成三段计费：编码器激活峰值、预填期 KV 瞬时写入、稳态 KV 驻留。准入控制必须显式估算单请求的视觉 token 数与总序列长度，而不是按请求数放行。KV cache 按总 token 数计费，视觉 token 与文本 token 共享同一预算，长图像请求会显著压缩可接纳并发。伪代码思路：</p>\n<ul>\n<li>读入图像尺寸与文本长度，按 <code>T_vis = ceil(H·W/P²)</code> 估算视觉 token 上界；</li>\n<li>乘以压缩率得到注入预算 <code>T_vis'</code>，加上文本长度得 <code>T_total</code>；</li>\n<li>用 <code>M_KV = 2·L·H_kv·d·T_total·b</code> 估算 KV 占用，叠加编码器桶内峰值激活；</li>\n<li>若超过显存档位余量，拒绝或降级到更低分辨率桶，而不是排队等待。</li>\n</ul>\n<p>代价是准入拒绝率上升与桶利用率下降；具体例子：同一批请求里混入少量超高分辨率图，按请求数切批会让整批的 KV 预算被这几条请求吃掉，正确做法是把它们单独放进高分辨率桶，用小批甚至单请求跑，牺牲这几条的吞吐换整批的稳定。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-41\">四十一 · 批抖动与尾延迟：按 token 预算切批，不按请求数</h3>\n<p>批抖动的根因是批内视觉 token 方差。图像分辨率差异大，按请求数切批会让短请求等待长请求，批内长尾直接拉高首 token 延迟分位。按视觉 token 预算切批可降低批内长尾与首 token 延迟方差，但预算设得过紧会让批变小、编码器延迟摊不薄；设得过松则长尾回归。分辨率分桶粒度是同一枚硬币的另一面：桶过细导致批小、桶过粗导致长尾，需按视觉 token 分布调参并监控分位延迟。</p>\n<p>监控上，除常规的首 token 延迟 P50/P99，还要单独记录批内视觉 token 方差与桶利用率。方差突然抬升通常意味着流量形态变化（例如一批文档扫描图涌入），此时应自动收紧切批预算或临时拆分高分辨率桶。视觉编码器前向是串行瓶颈，按分辨率分桶批处理可摊薄编码器延迟；若编码器与语言模型同卡，编码器批大小与语言侧批调度会互相牵制，尾延迟表现为“编码器批次一长，解码侧就饿”。</p>\n<div class=\"formula\">$$\\mathrm{Var}_{\\mathrm{batch}}=\\frac{1}{n}\\sum_{i}\\left(T_{\\mathrm{vis},i}^{\\prime}-\\bar{T}_{\\mathrm{vis}}^{\\prime}\\right)^{2},\\quad \\mathrm{SLO}_{\\mathrm{TTFT}}=P_{99}\\left(\\tau_{\\mathrm{enc}}+\\tau_{\\mathrm{prefill}}\\right)$$</div>\n<p>具体例子：视觉编码器与语言模型分离部署可解耦两类负载的批调度与精度策略，代价是跨节点传输视觉 token 特征，需计入通信开销与失败重试；分离后编码器侧可以按桶独立扩缩，尾延迟不再被解码侧的长批拖累，但特征传输的抖动会转移到预填阶段，需要单独设超时与重试预算。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-42\">四十二 · 静默降级：没有报错，只有分位在漂</h3>\n<p>静默降级是多模态服务最危险的一类失败：请求全部成功、输出语法通顺、错误率为零，但定位框开始系统性偏移、文本阅读在长文档上漏行、跨模态注意力对视觉 token 的利用率下降。触发源通常是渐进式的——压缩率被调高、分辨率分桶边界被挪动、视觉编码器换了精度档位，单条请求的差异落在噪声里，只有分位统计才看得出来。</p>\n<p>监控设计要把“质量”做成和延迟并列的一等指标：固定探针集上跑定位误差与 OCR 召回，按桶分别统计，因为不同分辨率桶的降级速度不同；同时记录视觉 token 的实际注入数与预算的比值，比值长期低于预算说明压缩合并模块在悄悄多降采样。跨模态注意力在预填阶段一次性注入视觉 token，解码阶段只读 KV，因此注入质量一旦下降无法在解码期补偿，探针必须卡在预填之后、解码之前。</p>\n<p>回滚策略要分级：压缩率与分桶边界属于配置级回滚，可灰度按桶回退；量化档位属于模型级回滚，代价是显存与吞吐同时回退，需预留显存档位。具体例子：某次把视觉编码器切到更低精度以腾 KV 空间，延迟分位改善但定位探针误差抬升，此时应只回滚视觉编码器精度、保留语言侧量化，因为塌陷源已由探针定位到视觉侧。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-43\">四十三 · 监控面与回滚闸门：把视觉 token 预算做成可观测变量</h3>\n<p>监控面按五段链路铺开：预处理与分桶（分辨率分布、桶利用率）、视觉编码器（桶内批大小、前向延迟、激活峰值）、压缩合并（实际注入 token 数与预算比值）、跨模态注入与预填（KV 写入量、总 token 数分布）、解码（首 token 延迟分位、稳态 KV 驻留）。每一段都要有独立的预算与告警阈值，而不是只看端到端错误率。视觉 token 数分布、批内方差与首 token 延迟分位是必须常驻的三个指标。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>可观测信号</th><th>定位手段</th><th>回滚闸门</th></tr></thead><tbody><tr><td>精度塌陷</td><td>定位误差、OCR 召回分位漂移</td><td>固定探针集按桶比对</td><td>配置级灰度回退压缩率</td></tr><tr><td>OOM</td><td>编码器峰值与预填 KV 叠加超限</td><td>三段显存计费拆解</td><td>准入拒绝或降分辨率桶</td></tr><tr><td>批抖动</td><td>批内视觉 token 方差抬升</td><td>按 token 预算重切批</td><td>收紧预算、拆高分辨率桶</td></tr><tr><td>尾延迟</td><td>TTFT P99 与桶利用率背离</td><td>编码器与解码侧批解耦</td><td>分离部署或独立扩缩</td></tr><tr><td>静默降级</td><td>注入 token 与预算比值下滑</td><td>预填后探针卡点</td><td>模型级回滚精度档位</td></tr></tbody></table>\n<p>回滚闸门的设计原则是“按桶、按段、可灰度”：桶级回滚避免一刀切影响低风险流量，段级回滚把视觉侧与语言侧分开，灰度回滚让探针集先验证再全量。代价是运维复杂度上升，但相比静默降级在全量流量上扩散，分段闸门的显存与吞吐代价是可控的。具体机制上，把压缩率、分桶边界、视觉编码器精度档位三个参数做成带版本的配置项，每次变更绑定一次探针回归，回归不通过则闸门自动回退到上一版本，并把该桶的准入上限临时下调，防止长图像请求继续突破并发上限。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-44\">四十四 · 分辨率分桶失效与视觉编码器显存挤占：诊断路径与回滚边界</h3>\n<p>本方案最脆弱的环节不是压缩率本身，而是分辨率分桶在真实流量分布下失去区分度。当请求图像尺寸集中在少数几个高分辨率档位时，桶内视觉 token 方差被压缩，但桶间负载极不均衡：少数超高分辨率桶独占视觉编码器批前向时间，其余桶排队等待，形成串行瓶颈下的尾延迟。诊断上应把<strong>视觉 token 数分布</strong>与<strong>桶内批大小</strong>作为一等监控指标，而非只看请求数或平均延迟。定位方法是按桶统计首 token 延迟分位（P50/P99）与批内视觉 token 方差：若某桶 P99 显著高于 P50 而批大小正常，说明该桶内部长尾；若某桶批大小长期偏低而 P99 高，说明桶粒度切得过细、批前向摊薄不足。回滚手段是把相邻桶合并、放宽桶边界，用更大的批换取编码器延迟摊薄，代价是批内方差回升，需同步收紧按视觉 token 预算切批的上限。</p>\n<p>第二个失效模式是视觉编码器与语言模型同卡部署时的显存挤占。编码器前向的峰值激活与语言模型 KV cache 共享同一显存档位，准入控制若只按 KV 预算估算并发，会在编码器峰值时刻触发 OOM。显存规划应把编码器峰值显存作为独立预留项，KV 可用预算为：</p>\n<div class=\"formula\">$$M_{\\mathrm{KV}}^{\\mathrm{avail}}=M_{\\mathrm{card}}-M_{\\mathrm{enc}}^{\\mathrm{peak}}-M_{\\mathrm{w}}-M_{\\mathrm{act}}^{\\mathrm{dec}}$$</div>\n<p>其中编码器峰值随桶内最大分辨率与批大小变化，必须按桶而非全局估算。诊断信号是 OOM 发生时伴随的桶分布偏移——若 OOM 集中在高分辨率桶且批大小接近上限，应优先下调该桶批大小或改为分时部署（编码器批前向与解码错峰），而非全局降并发。回滚到分离部署可彻底解耦两类峰值，代价是视觉 token 特征跨节点传输的通信开销与失败重试路径，需在监控中单列传输延迟与重试率。</p>\n<p>第三个失效模式是静默降级：压缩率与分辨率分桶必须与训练侧接口一致，推理时若因显存压力临时调高降采样率或改变位置编码的分桶边界，视觉 token 合并会破坏定位与文本阅读能力，而延迟与吞吐指标反而变好，监控不会报警。这类降级只能靠<strong>精度探针</strong>发现——在固定小样本上周期性跑定位与文本阅读任务，比对压缩率变更前后的输出一致性。诊断路径是把压缩率、桶边界、位置编码配置作为带版本的推理参数写入请求日志，任何参数漂移都触发探针复跑。回滚边界很明确：压缩率与桶边界属于与训练对齐的接口，不允许在运行时自适应调整；显存压力只能通过批大小、并发上限与部署拓扑消化，不能通过改压缩率消化。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>监控信号</th><th>定位手段</th><th>回滚动作</th></tr></thead><tbody><tr><td>桶内长尾</td><td>桶级 P99 首 token 延迟、批内 token 方差</td><td>按桶比对批大小与延迟分位</td><td>合并相邻桶、收紧 token 预算上限</td></tr><tr><td>编码器挤占 OOM</td><td>OOM 时的桶分布与批大小</td><td>编码器峰值显存独立核算</td><td>下调高分辨率桶批大小或分离部署</td></tr><tr><td>静默降级</td><td>压缩率/桶边界参数漂移</td><td>定位与文本阅读精度探针</td><td>锁定接口参数，仅调批与并发</td></tr></tbody></table>\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-45\">四十五 · 口径先于数字：把视觉 token 当计量单位</h3>\n<p>读 Qwen-VL 这类多模态推理的任何性能数字，第一步不是看吞吐或延迟，而是确认这个数字的分母是什么。文本 LLM 的批通常按请求数或 token 数计，多模态请求的“长度”由两部分拼成：视觉 token 与文本 token。视觉 token 数由分块分辨率决定，<span class=\"formula-inline\">T<sub>vis</sub></span> 随图像高宽乘积平方增长，再经压缩与合并模块降采样到预设预算。因此同一张图在不同分辨率桶、不同压缩率下对应完全不同的 KV 占用与预填计算量。一个“batch=8”的吞吐数字，若其中三张是长图、五张是短图，其有效负载与“batch=8 全是短图”不可比。工程上应把口径统一为总 token 预算：<span class=\"formula-inline\">T<sub>total</sub> = T′<sub>vis</sub> + T<sub>text</sub></span>，并同时报告该批的视觉 token 方差。方差是判断该数字是否可复用的关键——方差大的批，其首 token 延迟分位会被长请求拖尾，均值吞吐好看但 SLO 不达标。</p>\n<div class=\"formula\">$$T_{\\mathrm{vis}}=\\left\\lceil \\frac{H\\cdot W}{P^{2}}\\right\\rceil,\\quad T_{\\mathrm{total}}=T_{\\mathrm{vis}}^{\\prime}+T_{\\mathrm{text}},\\quad M_{\\mathrm{KV}}=2\\,L\\,H_{kv}\\,d\\,T_{\\mathrm{total}}\\,b$$</div>\n<p>上式的三个量必须一起报：<span class=\"formula-inline\">T′<sub>vis</sub></span>（压缩后的视觉 token）、<span class=\"formula-inline\">T<sub>text</sub></span>、批大小 <span class=\"formula-inline\">b</span>。只报 <span class=\"formula-inline\">b</span> 不报 <span class=\"formula-inline\">T<sub>total</sub></span> 的吞吐数字在多模态场景下没有意义。举例：同为 batch=16，若平均 <span class=\"formula-inline\">T<sub>total</sub></span> 从 2k 涨到 6k，KV 显存按线性膨胀三倍，可接纳并发随之下降，吞吐反而可能因抢占与重算而降低。这就是“数字怎么读”的第一条纪律：先问分母，再问方差。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-46\">四十六 · 硬件档位与精度口径：三档不可混算</h3>\n<p>Blackwell 部署至少涉及 B200、B300、GB200 NVL72 三类档位，显存容量、NVLink 拓扑与功耗包络不同，同一模型的并发上限与批容量因此不同。材料未给出各档位的具体显存与带宽数字，本部分只确立口径规则：任何吞吐或并发数字必须标注档位，跨档位比较只能定性。更隐蔽的是精度口径。NVFP4/FP8 对视觉编码器与语言模型的精度代价需分别评估——视觉特征经压缩合并后进入跨模态注意力，低精度量化在视觉侧可能放大定位与文本阅读的误差，而语言侧对权重量化更宽容。因此“FP8 下吞吐提升”这类表述必须拆成两段：视觉编码器是否量化、语言模型是否量化、KV cache 是否量化，三者口径不同则数字不可比。</p>\n<p>功耗口径同样如此。GB200 NVL72 是机柜级系统，其功耗与散热预算按整柜计，单卡吞吐数字若未说明是否在整柜功率封顶下测得，就无法与 B200 单机数字并列。工程判断是：容量规划时以“每瓦可接纳并发”作为跨档位的可比指标，而不是裸吞吐。公式上可写成 <span class=\"formula-inline\">C<sub>w</sub> = C<sub>max</sub> / P<sub>sys</sub></span>，其中 <span class=\"formula-inline\">C<sub>max</sub></span> 由 KV 显存反推，<span class=\"formula-inline\">P<sub>sys</sub></span> 为系统功率包络。材料未给出 <span class=\"formula-inline\">P<sub>sys</sub></span> 的具体值，但该比值是唯一能在不同档位间横向比较的量。</p>\n<table class=\"mini\"><thead><tr><th>口径项</th><th>必须标注</th><th>不可比的情形</th></tr></thead><tbody><tr><td>批大小</td><td>总 token 预算与视觉 token 方差</td><td>仅报请求数、未报分辨率分布</td></tr><tr><td>精度</td><td>视觉编码器/语言模型/KV 分别是否量化</td><td>混合精度未拆分</td></tr><tr><td>硬件</td><td>B200 / B300 / GB200 NVL72</td><td>跨档位直接比吞吐</td></tr><tr><td>功耗</td><td>单卡或整柜功率封顶</td><td>未说明功率约束</td></tr></tbody></table>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-47\">四十七 · TTFT 与 TPOT 的拆分：编码器是独立预算项</h3>\n<p>多模态请求的首 token 延迟不是单一量，它由预处理、视觉编码器前向、压缩合并、预填注入四段串行构成。视觉编码器是串行瓶颈，其延迟随分辨率桶与桶内批大小变化；按分辨率分桶批处理可摊薄编码器延迟，但桶过细导致批小、摊薄效果差，桶过粗导致批内长尾。因此 TTFT 必须拆成 <span class=\"formula-inline\">TTFT<sub>vis</sub></span> 与 <span class=\"formula-inline\">TTFT<sub>prefill</sub></span> 两项分别设预算，而不是合并成一个 SLO 数字。伪代码思路如下：调度器读取图像尺寸，估算 <span class=\"formula-inline\">T<sub>vis</sub></span>，按预算桶排队；桶内凑批后执行编码器前向；压缩合并输出固定预算视觉 token；预填阶段一次性注入 KV。TTFT 的方差主要来自桶内分辨率差异与编码器批等待时间。</p>\n<p>TPOT 的口径相对简单：解码阶段只读 KV，视觉 token 已固化在 KV 中，因此 TPOT 主要由语言模型解码的批内总 token 数与 KV 带宽决定，与图像分辨率无直接关系——前提是预填已完成。这意味着一个请求的“慢”可能全部落在 TTFT 上而 TPOT 正常，若只报平均延迟会掩盖编码器瓶颈。工程代价上，视觉编码器与语言模型同卡部署时，编码器峰值显存会挤压 KV cache 空间，导致可接纳并发下降；分离部署可解耦两类负载的批调度与精度策略，代价是跨节点传输视觉 token 特征，需计入通信开销与失败重试。举例：一个长图请求在编码器阶段占用峰值显存，若与解码批共享同一卡，解码批的 KV 预算被临时压缩，表现为 TPOT 抖动——这是同卡部署的典型代价，分离部署则把该抖动转为网络传输延迟。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-48\">四十八 · 吞吐的分母：并发上限由 KV 反推，不由请求数决定</h3>\n<p>多模态吞吐数字最常见的失真来自并发口径。KV cache 按总 token 数计费，视觉 token 与文本 token 共享同一预算，长图像请求会显著压缩可接纳并发。因此并发上限应由显存档位反推：<span class=\"formula-inline\">C<sub>max</sub> = M<sub>budget</sub> / M<sub>KV</sub>(T<sub>total</sub>)</span>，其中 <span class=\"formula-inline\">M<sub>budget</sub></span> 是扣除权重与编码器峰值后的可用显存。材料未给出具体显存数字，但该式确立了口径：报“支持 N 并发”时必须同时报平均 <span class=\"formula-inline\">T<sub>total</sub></span> 与压缩率，否则该并发数在长图负载下不成立。把视觉 token 当作固定开销会导致 KV 预算失真，长图像请求会突破并发上限，触发抢占与重算，吞吐数字虚高而尾延迟恶化。</p>\n<p>吞吐的另一个口径问题是“按请求计”还是“按 token 计”。多模态请求的 token 数差异可达数倍，按请求计的吞吐会奖励短请求、掩盖长请求成本。工程上应以每秒处理的视觉 token 数与文本 token 数分别报告，或统一为每秒总 token 数。准入控制需显式估算 <span class=\"formula-inline\">T<sub>total</sub></span> 后再决定是否接纳，而不是先收后挤。举例：同一系统在短图负载下报出的请求吞吐，换成长图负载后按 token 计的吞吐可能持平甚至下降，因为编码器与预填成本上升而解码占比下降——这不是系统变慢，而是口径变了。跨负载比较必须固定分辨率分布。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-49\">四十九 · 哪些提升不可比：五类常见错配</h3>\n<p>第一类错配是分辨率分布不同。两个系统报同一吞吐，若一个负载以低分辨率为主、另一个以高分辨率为主，视觉 token 数差异直接改变 KV 与预填成本，数字不可比。第二类是压缩率不同。压缩与合并模块的降采样率直接决定单请求显存占用与批容量，压缩率越高预填与 KV 写入越省，但定位与文本阅读精度需权衡；一个高压缩率的吞吐数字不能与低压缩率的精度数字并列宣称“又快又准”。第三类是桶粒度不同。分辨率分桶粒度影响批内方差与桶利用率，桶过细批小、桶过粗长尾，两个系统的分桶策略不同则 TTFT 分位不可比。</p>\n<p>第四类是部署形态不同。视觉编码器与语言模型同卡还是分离，决定了显存竞争与通信开销的存在与否，同卡方案的吞吐数字不含跨节点传输成本，分离方案含，两者不可直接比较。第五类是精度口径不同，如第二节所述，视觉侧与语言侧是否量化必须拆分。材料未给出量化方案与 NVFP4/FP8 下的精度代价，因此任何“量化后吞吐提升”的表述在本卷中只能定性，不能作为跨系统比较依据。工程判断是：看到提升数字先做五项核对——分辨率分布、压缩率、桶粒度、部署形态、精度拆分，缺一项即标记为不可比。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-50\">五十 · 监控口径：把分位与方差写进指标</h3>\n<p>可复用的性能口径最终要落到监控上。需覆盖的量包括：视觉 token 数分布（按分辨率桶统计）、批内视觉 token 方差、TTFT 分位（并拆出编码器段）、TPOT 分位、KV 占用按总 token 数的水位、以及每瓦可接纳并发。批内方差是预警指标——方差上升预示长尾即将拉高 TTFT 分位，此时应调整桶粒度或切批策略，而非等 SLO 违约后补救。视觉编码器延迟需单独设预算，因为它是串行瓶颈且与解码负载解耦；若与语言模型同卡，还需监控编码器峰值显存对 KV 水位的挤压。</p>\n<p>指标口径必须与调度参数绑定：切批按视觉 token 预算而非请求数，则监控也应按预算桶聚合，否则均值会被短请求稀释。举例：某桶内 90 分位 TTFT 超标而均值正常，说明桶内混入了超预算长图，应细化该桶或对该分辨率段单独限流。最后一条工程判断：任何对外报出的吞吐或延迟数字，都应附带其口径五元组（档位、精度拆分、分辨率分布、压缩率、部署形态），否则该数字在容量规划中不可用——口径不完整的数字，比没有数字更危险。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-51\">五十一 · 视觉 token 预算下的口径边界与失效条件</h3>\n<p>读这一节的数字，先要承认一个前提：Qwen-VL 的推理成本不是“每请求一个常数”，而是随分辨率平方漂移的随机变量。视觉 token 数 $T_{\\mathrm{vis}}=\\lceil H\\cdot W/P^{2}\\rceil$ 经压缩合并降到预算 $T_{\\mathrm{vis}}^{\\prime}$，再与文本拼接成 $T_{\\mathrm{total}}$，KV 占用 $M_{\\mathrm{KV}}=2LH_{kv}d\\,T_{\\mathrm{total}}\\,b$。因此任何吞吐或并发数字，只有在标注了分辨率分布、压缩率、桶粒度与批切分口径后才可比；同一模型在 448 与 1024 分辨率下的“每秒请求数”属于两个不同的系统。跨条目已讲过的预处理与注入链路此处不再展开，本节只谈这些口径在什么条件下失效。</p>\n<p>第一个失效条件是按请求数切批。批内视觉 token 方差过大时，短请求被长请求拖住，首 token 延迟分位被拉高，而平均吞吐看起来仍然正常——这是最容易被误读为“提升”的假象。正确口径是按视觉 token 预算切批，把批内 $T_{\\mathrm{total}}$ 的方差压到可控范围；代价是桶利用率下降、批变小、编码器摊薄效果变差。分辨率分桶粒度同样两头受挤：桶过细导致批小、编码器前向次数增多；桶过粗导致长尾，分位延迟恶化。表里给出三种口径下同一批请求的可比性判断。</p>\n<table class=\"mini\"><thead><tr><th>口径</th><th>可比性</th><th>主要代价</th></tr></thead><tbody><tr><td>按请求数切批</td><td>不可比，长尾掩盖</td><td>首 token 延迟方差大</td></tr><tr><td>按视觉 token 预算切批</td><td>需标注预算值</td><td>桶利用率与批大小下降</td></tr><tr><td>编码器与语言模型分离部署</td><td>需计入跨节点通信</td><td>特征传输与失败重试开销</td></tr></tbody></table>\n<p>第二个失效条件是显存口径混算。视觉编码器与语言模型同卡部署时，编码器峰值显存会挤压 KV cache 空间，此时报出的“最大并发”是在编码器峰值时刻的瞬时值，而非稳态值；分离部署虽解耦了两类负载的批调度与精度策略，却把跨节点传输视觉特征、通信开销与失败重试引入延迟链路，TTFT 的分位尾部会明显变厚。功耗口径同理：编码器批前向是短时高占用，与解码阶段的持续低占用不是同一类负载，混在一起算每 token 能耗没有意义。</p>\n<p>第三个失效条件是精度口径。材料未给出量化方案，NVFP4/FP8 下视觉编码器与语言模型的精度代价必须分别评估：视觉特征对低精度更敏感的可能性需实测，压缩率越高预填与 KV 写入越省，但定位与文本阅读精度需权衡，而这一权衡不会体现在吞吐数字里。工程判断是：任何跨硬件档位（B200/B300/GB200 NVL72）、跨 batch、跨并发的对比，只要没有同时固定分辨率分布、压缩率、桶粒度与切批规则，就应视为不可比；准入控制中必须显式估算 $T_{\\mathrm{total}}$，否则长图像请求会直接突破并发上限。</p>\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-52\">五十二 · 迁移的第一道闸门：压缩率与位置编码的耦合</h3>\n<p>把 Qwen-VL 的推理链路搬到别的模型上，最先撞上的不是算子，而是压缩率与位置编码的接口约定。视觉 token 压缩与合并模块的降采样率不是自由旋钮：它决定了注入语言模型的序列长度，而跨模态注意力的位置编码与分辨率分桶必须在推理时与训练侧完全一致。换模型时若只改压缩率而不改位置编码的重排规则，视觉 token 合并会直接破坏定位与文本阅读能力——这两项恰恰是 Qwen-VL 的建模目标，也是迁移时最容易被牺牲的能力。工程判断是：压缩率只能在训练侧已对齐的取值集合内选择，推理侧的调参空间是分桶粒度与批预算，不是降采样率本身。</p>\n<p>代价体现在两处。其一，压缩率提高使预填计算与 KV 写入线性下降，但定位精度按定性方式退化，且退化不可通过后处理恢复；其二，若为保精度而压低压缩率，视觉 token 数按分辨率平方增长，KV 占用随总 token 数线性上升。用公式表达单请求的显存下限：</p>\n<div class=\"formula\">$$M_{\\mathrm{KV}}=2\\,L\\,H_{kv}\\,d\\,T_{\\mathrm{total}}\\,b,\\quad T_{\\mathrm{total}}=T_{\\mathrm{vis}}^{\\prime}+T_{\\mathrm{text}}$$</div>\n<p>其中 $T_{\\mathrm{vis}}^{\\prime}$ 是压缩合并后的视觉 token 数。举例：同一张高分辨率文档图，压缩率减半意味着 $T_{\\mathrm{vis}}^{\\prime}$ 翻倍，KV 预算与可接纳并发同时被压缩，而收益只是文本阅读精度上的一点余量——这笔账必须在迁移前算清，而不是部署后再回退。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-53\">五十三 · 分辨率分桶的迁移：桶边界随模型重画</h3>\n<p>分桶策略看似与模型无关，实则强耦合于视觉编码器的分块方式与压缩模块的输入约束。迁到另一个视觉编码器时，patch 尺寸、可接受输入分辨率集合、是否支持动态分辨率都变了，原来的桶边界会失效：桶过细导致每桶批小、编码器利用率低；桶过粗导致批内视觉 token 方差大、长尾拉高首 token 延迟分位。正确做法是以视觉 token 分布的分位数为依据重画桶边界，而不是照搬原模型的桶表。</p>\n<p>伪代码思路如下，调度器在准入阶段完成估算与归桶：</p>\n<ul>\n<li>读取图像 $H,W$ 与文本长度，按 $\\lceil H\\cdot W/P^{2}\\rceil$ 估算原始视觉 token 数；</li>\n<li>乘以压缩率得到 $T_{\\mathrm{vis}}^{\\prime}$，加上 $T_{\\mathrm{text}}$ 得 $T_{\\mathrm{total}}$；</li>\n<li>按 $T_{\\mathrm{total}}$ 落入的桶排队，桶内按总 token 预算而非请求数切批；</li>\n<li>若桶内方差超过阈值，拆批或延迟入队，避免短请求被长请求拖尾。</li>\n</ul>\n<p>系统代价是桶数量与桶利用率之间的权衡：桶多则批小、编码器前向摊薄不足，首 token 延迟上升；桶少则批内方差大，延迟分位变差。迁移到图像分辨率分布更离散的领域（如遥感、医学影像）时，桶边界必须重估，否则原桶表会把大部分请求挤进少数几个桶，批内方差失控。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-54\">五十四 · 分离部署的边界：通信开销吃掉多少收益</h3>\n<p>视觉编码器与语言模型分离部署可解耦两类负载的批调度与精度策略，这是迁移到异构集群时最有价值的杠杆。但它的适用边界很明确：跨节点传输的是压缩后的视觉 token 特征，其体积与 $T_{\\mathrm{vis}}^{\\prime}\\times d$ 成正比。压缩率越高，传输越省，分离部署越划算；压缩率低或分辨率极高时，特征传输会占用可观的链路带宽，并与语言侧的 KV 读写争抢资源。</p>\n<p>判断标准是单位请求的传输字节与预填计算量的比值。若传输开销接近甚至超过编码器前向节省的时间，分离部署就失去意义，应退回同卡分时部署。迁移到 NVLink 5 域内的 GB200 NVL72 时，机架内带宽充裕，分离部署的通信代价被压低；迁到跨机架或跨集群拓扑时，同一策略的代价结构完全不同，必须重新测算。另一项隐性代价是失败重试：视觉侧与语言侧分离后，特征传输失败需要重放编码器前向或缓存特征，重试逻辑会放大尾延迟。</p>\n<p>同卡部署的边界同样清晰：编码器峰值显存会挤压 KV cache 空间。举例：一个高分辨率桶的批前向在编码器侧产生瞬时峰值，若与语言模型共享显存，KV 预算被临时压缩，准入控制必须为编码器峰值预留显存水位，否则并发上限在高峰期失真。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-55\">五十五 · 量化的迁移风险：视觉特征比文本更敏感</h3>\n<p>材料未给出量化方案，也未给出 NVFP4/FP8 下视觉编码器与语言模型的精度代价，因此迁移时不能假定文本侧的量化经验可直接复用。视觉编码器输出的是连续特征，跨模态注入后参与定位与文本阅读这类细粒度任务，对低精度的敏感度需分别实测；语言模型侧的 KV cache 量化与权重量化则是另一套评估口径。工程判断是：视觉编码器与语言模型分开做精度规划，先在小规模分辨率桶上验证定位与阅读指标，再放开到全量桶。</p>\n<p>代价结构上，量化降低的是显存占用与带宽需求，直接抬高可接纳并发；但若视觉侧量化引入特征偏差，压缩合并模块的降采样会放大该偏差，最终表现为定位框偏移或文本漏读。这类退化不会在吞吐指标上暴露，只能靠任务级指标监控。迁移到以文本阅读为主的生产负载时，视觉侧量化的收益与风险不对称，宜保守；迁移到以粗粒度图文匹配为主的负载时，激进量化的下行风险小得多。</p>\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-56\">五十六 · 规模上限：三个约束谁先撞墙</h3>\n<p>这套方案的上限由三个约束中最先饱和者决定，迁移到不同规模时必须先判断是哪一个。第一是 KV 显存：$T_{\\mathrm{total}}$ 随分辨率与并发线性增长，长图像请求会显著压缩可接纳并发，准入控制若不显式估算视觉 token，并发上限会被悄悄突破。第二是视觉编码器的串行前向：它是每请求必经的串行段，分桶批处理只能摊薄、不能消除，高并发下编码器吞吐成为硬上限。第三是批内方差带来的延迟分位恶化：即使平均吞吐达标，首 token 延迟的高分位仍可能击穿 SLO。</p>\n<p>判断顺序应是：先按显存档位反推 KV 可支撑的并发上限，再测编码器在目标桶分布下的吞吐上限，两者取小；若前者远大于后者，说明瓶颈在编码器，应优先分离部署与分桶优化；若后者远大于前者，说明瓶颈在 KV，应优先提高压缩率或收紧准入。迁移到更大集群时，KV 约束随卡数线性放松，编码器约束却随分桶粒度与批大小非线性变化，因此规模扩大后瓶颈往往从 KV 转向编码器——这是迁移时最常被误判的一步。</p>\n<p>材料未给出具体档位数据与 SLO 指标，上述判断只能定性执行，但方向明确：把视觉 token 预算作为一等调度参数，把分辨率分桶、压缩率与 KV 计费绑定到批调度，并在迁移时逐项重测桶边界、传输代价与量化敏感度。任何跳过这三项重测、直接复用原配置的迁移，都会在长图像请求的比例上升时暴露为并发上限失真与首 token 延迟分位劣化。</p>\n\n\n<h3 id=\"paper-qwen-vl-a-versatile-vision-language-2023-sec-57\">五十七 · 边界在哪里：迁移到别的模型与领域时要重算的那几个量</h3>\n<p>这套方案能迁，但迁的时候不能搬配置，只能搬三个约束：视觉 token 预算、分辨率分桶、编码器与语言模型的解耦边界。换模型时最先失效的是压缩率假设。压缩与合并模块的降采样率决定了注入语言模型的序列长度，而它和训练时的位置编码、分辨率分桶是绑定的；换一个视觉编码器或换一种跨模态注入方式，压缩率必须重新与训练接口对齐，否则视觉 token 合并会直接破坏定位与文本阅读能力。工程上判断能否直接复用，看一条：新模型的视觉 token 数是否仍随分辨率平方增长，即 <span class=\"formula\">$$T_{\\mathrm{vis}}=\\left\\lceil \\frac{H\\cdot W}{P^{2}}\\right\\rceil$$</span> 若分块策略变成动态分辨率或原生分辨率切图，桶的划分逻辑要重写，按固定 P 估出的 token 预算会系统性偏低，准入控制随之失真。领域迁移同理：文档阅读类请求分辨率高、文本 token 少，KV 几乎全由视觉 token 占据；而图文问答类请求文本占比高，同一套桶粒度会造成桶利用率两极分化。</p>\n<p>失效条件集中在三处。其一，把视觉 token 当固定开销计费。KV 占用按 <span class=\"formula\">$$M_{\\mathrm{KV}}=2\\,L\\,H_{kv}\\,d\\,T_{\\mathrm{total}}\\,b,\\quad T_{\\mathrm{total}}=T_{\\mathrm{vis}}^{\\prime}+T_{\\text{text}}$$</span> 计，长图像请求会显著压缩可接纳并发，若准入时不显式估算 <span class=\"formula\">$$T_{\\mathrm{vis}}^{\\prime}$$</span>，并发上限会被长尾请求突破。其二，视觉编码器与语言模型同卡部署。编码器前向是串行瓶颈，其峰值显存会挤压 KV cache 空间，批越大挤压越明显；分离部署可解耦两类负载的批调度与精度策略，代价是跨节点传输视觉 token 特征，通信开销与失败重试要计入首 token 延迟预算。其三，按请求数而非 token 预算切批。分辨率差异使批内长度不齐，短请求等长请求，首 token 延迟分位被拉高，这种拖尾在桶过粗时最严重。</p>\n<p>规模上限由两个比值决定，而不是由卡数决定。第一个是压缩率与精度要求的比值：压缩率越高，预填计算与 KV 写入越省，但定位与文本阅读精度需权衡，材料未给出量化方案，NVFP4/FP8 下视觉编码器与语言模型的精度代价需分别评估，视觉特征对低精度更敏感的可能性必须实测，不能靠语言模型侧的量化经验外推。第二个是编码器吞吐与语言模型解码吞吐的比值：编码器按桶批处理可摊薄延迟，但桶过细导致批小、桶过粗导致长尾，桶粒度需按视觉 token 分布调参并监控分位延迟。迁移判断可落成一张对照表：</p>\n<table class=\"mini\"><thead><tr><th>迁移对象</th><th>必须重算的量</th><th>不适用情形</th></tr></thead><tbody><tr><td>换视觉编码器</td><td>压缩率、分块 P、位置编码对齐</td><td>动态分辨率切图，固定桶失效</td></tr><tr><td>换语言模型</td><td>KV 每 token 字节数、层数与 KV 头数</td><td>MLA 类压缩 KV，公式需改写</td></tr><tr><td>换领域</td><td>视觉/文本 token 占比、桶粒度</td><td>文本主导请求，视觉预算不再是瓶颈</td></tr><tr><td>换精度</td><td>编码器与语言模型分别评估</td><td>视觉特征低精度敏感，需实测</td></tr></tbody></table>\n<p>最后一处工程判断落在监控口径上：迁移后若只盯吞吐，会掩盖批内方差恶化。应把视觉 token 数分布、批内方差与首 token 延迟分位作为一组联动指标，任一漂移都说明桶粒度或压缩率与新模型不匹配；此时先调桶，再调压缩率，最后才动精度，因为前两者不改变数值语义，后者会改变定位与阅读能力的边界。</p>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 138\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"52.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Qwen-VL: A Versatile </text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Vision-Language Mo…</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"74.0\" x2=\"271.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 69.5 L 270.0 78.5 L 278.0 74.0 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"74.0\" x2=\"515.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 69.5 L 514.0 78.5 L 522.0 74.0 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"128.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2023 · arXiv preprint</text></svg><figcaption><b>家谱</b> · Qwen-VL: A Versatile Vi… 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>材料未给出具体评测数据集</td></tr><tr><td>基线</td><td>材料未给出对比基线</td></tr><tr><td>主要结果</td><td>材料未给出吞吐、延迟或精度数字；可确认的机制是视觉 token 数随分辨率…</td></tr><tr><td>消融</td><td>材料未给出消融实验；推理侧应关注压缩率、分辨率分桶粒度与视觉编码器批大小对…</td></tr><tr><td>局限</td><td>材料未给出失败模式与监控指标；推理侧风险集中在分辨率分桶不均导致的批内长尾…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-qwen-vl-a-versatile-vision-language-2023 · 共 9 个片段</p>\n";break;}}})();
